var BT_BOI_CANH = {"ho hoan kiem":{"bai":"Hồ Hoàn Kiếm","t":"Hồ Hoàn Kiếm còn được gọi là Hồ Gươm là một hồ nước ngọt tự nhiên nằm ở phường Hoàn Kiếm, trung tâm thành phố Hà Nội. Hồ có diện tích khoảng 12 ha. Trước kia, hồ còn có các tên gọi là hồ Lục Thủy (vì nước có màu xanh quanh năm), hồ Thủy Quân (dùng để duyệt thủy binh), hồ Tả Vọng và Hữu Vọng (trong thời Lê mạt)."},"pho co ha noi":{"bai":"Khu phố cổ Hà Nội","t":"Khu phố cổ Hà Nội là tên gọi thông thường của một khu vực đô thị có từ lâu đời của Hà Nội nằm ở ngoài hoàng thành Thăng Long. Khu đô thị này tập trung dân cư hoạt động tiểu thủ công nghiệp và buôn bán giao thương, hình thành lên những phố nghề đặc trưng, mang những nét truyền thống riêng biệt của cư dân thành thị, kinh đô."},"van mieu quoc tu giam":{"bai":"Văn Miếu – Quốc Tử Giám","t":"Văn Miếu – Quốc Tử Giám là quần thể di tích đa dạng, phong phú hàng đầu của thành phố Hà Nội, nằm ở phía Nam kinh thành Thăng Long. Quần thể kiến trúc Văn Miếu – Quốc Tử Giám bao gồm: hồ Văn, khu Văn Miếu – Quốc Tử Giám và vườn Giám, mà kiến trúc chủ thể là Văn miếu - nơi thờ Khổng Tử, và Quốc tử giám - trường đại học đầu tiên của Việt Nam."},"hoang thanh thang long":{"bai":"Hoàng thành Thăng Long","t":"Hoàng thành Thăng Long là quần thể di tích gắn với lịch sử hình thành kinh thành Thăng Long – Hà Nội. Công trình kiến trúc đồ sộ này được các triều vua xây dựng trong nhiều giai đoạn lịch sử và trở thành di tích quan trọng bậc nhất trong hệ thống các di tích Việt Nam."},"quang truong ba dinh lang chu tich ho chi minh chua mot cot":{"bai":"Quảng trường Ba Đình","t":"Quảng trường Ba Đình là quảng trường quan trọng nhất ở Việt Nam, nằm trên đường Hùng Vương, phường Ba Đình và là nơi Lăng Chủ tịch Hồ Chí Minh được xây dựng."},"ho tay chua tran quoc":{"bai":"Hồ Tây","t":"Hồ Tây (với các tên gọi khác trong lịch sử như Đầm Xác Cáo, Hồ Kim Ngưu, Lãng Bạc, Dâm Đàm, Đoài Hồ) là hồ tự nhiên lớn nhất thành phố Hà Nội, hiện thuộc địa phận phường Tây Hồ. Đây là một hồ móng ngựa và là vết tích của dòng chảy cũ của sông Hồng. Hồ có diện tích hơn 500 ha với chu vi là khoảng 14,8 km."},"nha hat lon ha noi":{"bai":"Nhà hát Lớn Hà Nội","t":"Nhà hát Lớn Hà Nội là một công trình kiến trúc tại thành phố Hà Nội, Việt Nam, phục vụ biểu diễn nghệ thuật. Nhà hát tọa lạc trên quảng trường Cách mạng tháng Tám, vị trí ở số 1A phố Tràng Tiền, phường Cửa Nam, thành phố Hà Nội, không xa hồ Hoàn Kiếm và Bảo tàng Lịch sử Việt Nam, cạnh khách sạn Hilton Hanoi Opera, nhìn ra các vườn hoa Nhà hát Lớn và vườn hoa 19-8."},"lang gom bat trang":{"bai":"Gốm Bát Tràng","t":"Gốm Bát Tràng là tên gọi chung của các loại đồ gốm Việt Nam được sản xuất tại làng Bát Tràng, thuộc xã Bát Tràng, thành phố Hà Nội và xã Phụng Công, tỉnh Hưng Yên. Tên gọi Bát Tràng có thể hiểu là \"cái đình lớn chuyên sản xuất bát\". Tuy nhiên, theo một số tài liệu khác, tên gọi Bát Tràng có thể bắt nguồn từ tên gọi Bạch Thổ Phường, nghĩa là \"phường đất sét trắng”."},"chua huong":{"bai":"Chùa Hương","t":"Chùa Hương (cách gọi dân gian) hay Hương Sơn là một quần thể văn hóa - tôn giáo của Việt Nam, gồm hàng chục ngôi chùa thờ Phật, các ngôi đền thờ Thần và các ngôi đình thờ tín ngưỡng nông nghiệp. Trung tâm của cụm đình đền chùa này là chùa Hương (tức chùa Trong) nằm trong động Hương Tích ở hữu ngạn sông Đáy, thuộc xã Hương Sơn, Hà Nội."},"lang co duong lam":{"bai":"Đường Lâm","t":"Đường Lâm là một địa danh tại miền Bắc Việt Nam. Địa danh Đường Lâm từng được sử dụng nhiều lần trong lịch sử Việt Nam cho những phạm vi hành chính khác nhau. Ngày nay, phạm vi Đường Lâm được chỉ một cụm các làng cổ tại khu vực phường Sơn Tây, thành phố Hà Nội. Khu vực Đường Lâm nằm bên hữu ngạn sông Hồng (bờ phía Nam), cạnh đường Quốc lộ 32, tại ngã ba giao cắt với Quốc lộ 21A."},"vuon quoc gia ba vi":{"bai":"Vườn quốc gia Ba Vì","t":"Vườn quốc gia Ba Vì là một vườn quốc gia ở Việt Nam, được thành lập năm 1991 theo quyết định số 17-CT ngày 16 tháng 1 năm 1991 của Chủ tịch Hội đồng Bộ trưởng Việt Nam."},"lang lua van phuc":{"bai":"Làng lụa Vạn Phúc","t":"Làng lụa Hà Đông hay Làng lụa Vạn Phúc (nay thuộc phường Hà Đông, cách trung tâm Hà Nội khoảng 10 km) là một làng nghề dệt lụa tơ tằm đẹp nổi tiếng có từ ngàn năm trước. Lụa Vạn Phúc có nhiều mẫu hoa văn và lâu đời bậc nhất Việt Nam. Lụa Hà Đông từng được chọn may trang phục cho triều đình."},"dao cat ba vinh lan ha":{"bai":"Cát Bà (đảo)","t":"Cát Bà là hòn đảo lớn nhất thuộc nhóm quần đảo Cát Bà trong vịnh Bắc Bộ, về mặt hành chính thuộc đặc khu Cát Hải, thành phố Hải Phòng, Việt Nam."},"vuon quoc gia cat ba":{"bai":"Vườn quốc gia Cát Bà","t":"Vườn quốc gia Cát Bà là khu rừng đặc dụng của Việt Nam, khu dự trữ sinh quyển thế giới. Vườn quốc gia Cát Bà trực thuộc Ủy ban nhân dân thành phố Hải Phòng quản lý, có trụ sở chính đóng trên địa bàn đặc khu Cát Hải, Hải Phòng."},"phao dai than cong":{"bai":"Pháo đài Thần công","t":"Pháo đài Thần công được xây dựng từ năm 1942 tại vị trí chiến lược trọng yếu tại cửa ngõ Biển Đông thuộc đảo Cát Bà, huyện đảo Cát Hải, thành phố Hải Phòng với nhiệm vụ giữ gìn vùng biển tiền tiêu của Việt Nam trong thời kỳ chiến tranh chống Pháp và chiến tranh chống Mỹ. Giờ đây, chứng tích này đã trở thành một điểm du lịch của huyện đảo Cát Hải."},"ga hai phong":{"bai":"Ga Hải Phòng","t":"Ga Hải Phòng là ga tàu hỏa chính tại thành phố Hải Phòng, Việt Nam. Ga Hải Phòng là ga hành khách cuối cùng trên tuyến đường sắt Hà Nội - Hải Phòng. Ngoài ra, ga Hải Phòng còn có tuyến đường sắt chạy đến cảng Hải Phòng chở hàng hóa từ cảng đến các vùng sâu trong nội địa bằng đường sắt."},"nha hat lon hai phong quang truong":{"bai":"Nhà hát Lớn Hải Phòng","t":"Nhà hát Lớn Hải Phòng, hay được biết với tên gọi chính thức là Nhà hát Thành phố, là nơi tổ chức những hoạt động văn hóa, chính trị lớn của thành phố Hải Phòng, Việt Nam. Hiện tại, nhà hát đang được Trung tâm tổ chức biểu diễn nghệ thuật - Thành phố Hải Phòng quản lý. Trong lịch sử Pháp thuộc, Việt Nam có 3 thành phố được chọn xây dựng nhà hát lớn đó là Hà Nội, Hải Phòng, Sài Gòn."},"khu di tich con son kiep bac":{"bai":"Khu di tích Côn Sơn – Kiếp Bạc","t":"Khu di tích Côn Sơn – Kiếp Bạc là một di tích quốc gia đặc biệt quan trọng của Việt Nam. Quần thể di tích này thuộc địa bàn phường Trần Hưng Đạo, thành phố Hải Phòng."},"dao co chi lang nam":{"bai":"Đảo Cò Chi Lăng Nam","t":"Đảo Cò Chi Lăng Nam là một khu du lịch sinh thái nổi tiếng ở Hải Phòng. Nơi đây có cảnh quan thiên nhiên rộng mở, thoáng đãng, bình yên đậm chất nông thôn Bắc Bộ. Đến với Đảo cò Chi Lăng Nam du khách sẽ được ngồi thuyền thưởng ngoạn cảnh sắc cực kỳ ấn tượng. Một hòn đảo nhỏ nằm giữa mặt hồ mênh mông nước. Từng đàn cò trắng bay rợp trời ríu rít gọi nhau về tổ."},"vinh ha long":{"bai":"Vịnh Hạ Long","t":"Vịnh Hạ Long là một vịnh nhỏ thuộc phần bờ tây vịnh Bắc Bộ tại khu vực biển Đông Bắc Việt Nam, bao gồm vùng biển đảo của khu vực đô thị Hạ Long thuộc thành phố Quảng Ninh."},"dao tuan chau":{"bai":"Đảo Tuần Châu","t":"Tuần Châu là một hòn đảo trong vịnh Hạ Long, thuộc quyền quản lý hành chính của phường Tuần Châu, thành phố Quảng Ninh, Việt Nam."},"bao tang quang ninh":{"bai":"Bảo tàng Quảng Ninh","t":"Bảo tàng Quảng Ninh là bảo tàng công lập đầu ngành của thành phố Quảng Ninh. Bảo tàng Quảng Ninh là đơn vị sự nghiệp trực thuộc Sở Văn hóa và Thể thao thành phố Quảng Ninh; thực hiện chức năng sưu tầm, bảo quản, nghiên cứu, trưng bày, giới thiệu di sản văn hóa, bằng chứng vật chất về lịch sử, văn hóa, thiên nhiên, con người Quảng Ninh và Việt Nam."},"chua ba vang":{"bai":"Chùa Ba Vàng","t":"Chùa Ba Vàng (còn gọi là Bảo Quang Tự) là một ngôi chùa tọa lạc ở lưng chừng núi Thành Đẳng, thuộc phường Uông Bí, thành phố Quảng Ninh."},"vinh bai tu long":{"bai":"Vịnh Bái Tử Long","t":"Vịnh Bái Tử Long là một vịnh nằm trong vịnh Bắc Bộ ở vùng Đồng bằng sông Hồng của Việt Nam. Vịnh Bái Tử Long bao gồm một vùng biển của đặc khu Vân Đồn, thành phố Quảng Ninh."},"cau bai chay pho dem hon gai":{"bai":"Cầu Bãi Cháy","t":"Cầu Bãi Cháy nằm trên quốc lộ 18, nối hai phường Hồng Gai và Bãi Cháy qua vịnh Cửa Lục nơi đổ ra vịnh Hạ Long, thuộc địa phận thành phố Quảng Ninh. Sau 20 năm lên kế hoạch cầu mới được hoàn thành. Cầu được xác định là công trình trọng điểm quốc gia, có vị trí chiến lược về giao thông, kinh tế và quốc phòng được Công an Thành phố Quảng Ninh bảo vệ."},"dao co to":{"bai":"Đảo Cô Tô","t":"Đảo Cô Tô, còn gọi là đảo Cô Tô Lớn, là một hòn đảo thuộc quần đảo Cô Tô trong vịnh Hạ Long, thuộc quyền quản lý hành chính của đặc khu Cô Tô, thành phố Quảng Ninh, Việt Nam. Trước 2025, từng tồn tại thị trấn Cô Tô, đặt trên đảo Cô Tô, là huyện lỵ huyện Cô Tô, tỉnh Quảng Ninh. Thị trấn có diện tích 6,5 km², dân số năm 1999 là 2.010 người, mật độ dân số đạt 309 người/km²."},"binh lieu":{"bai":"Bình Liêu (định hướng)","t":"Bình Liêu có thể là một trong số các địa danh sau đây: Xã Bình Liêu, thành phố Quảng Ninh."},"dao ti top":{"bai":"Đảo Ti Tốp","t":"Đảo Titov là đảo nhỏ trong vịnh Hạ Long, về mặt hành chính thuộc phường Hồng Gai, thành phố Quảng Ninh, Việt Nam. Hòn đảo cách cảng tàu du lịch Bãi Cháy khoảng 7–8 km về hướng Đông Nam. Hòn đảo nhỏ tựa lưng vào vịnh Cửa Lục, phía trước là hang Sửng Sốt có đảo Bồ Hòn, bên phải là hòn Dầm Nam và phía bắc là hòn Dầm Bắc."},"hang sung sot":{"bai":"Hang Sửng Sốt","t":"Hang Sửng Sốt là một hang động dạng karst trong khối núi đá vôi của đảo Bồ Hòn, vịnh Hạ Long, thành phố Quảng Ninh, Việt Nam."},"chua dau":{"bai":"Chùa Dâu","t":"Chùa Dâu , Pháp Vân , hay Cổ Châu) là một ngôi chùa nằm ở phường Trí Quả, thành phố Bắc Ninh, cách Hà Nội khoảng 30 km. Đây là trung tâm Phật giáo cổ xưa nhất của Việt Nam. Chùa còn được người dân gọi với những tên gọi khác nhau như chùa Cả, Cổ Châu tự, Diên Ứng tự, Thiền Định tự."},"chua phat tich":{"bai":"Chùa Phật Tích","t":"Chùa Phật Tích còn gọi là chùa Vạn Phúc là một ngôi chùa nằm ở sườn phía Nam núi Phật Tích (còn gọi núi Lạn Kha, non Tiên), xã Phật Tích, thành phố Bắc Ninh. Trong chùa có tượng đức Phật bằng đá thời nhà Lý lớn nhất Việt Nam."},"chua but thap":{"bai":"Chùa Bút Tháp","t":"Chùa Bút Tháp nằm ở bên đê hữu ngạn sông Đuống, khu Bút Tháp, phường Trí Quả, thành phố Bắc Ninh. Ngoài ra, nhân dân trong vùng còn gọi là chùa Nhạn Tháp, chùa Thấp. Tên cũ của chùa trước đây gồm có: Thiếu Lâm Tự, Hoàng Cung Tự. Trong chùa có tượng Quan Âm thiên thủ thiên nhãn bằng gỗ lớn nhất Việt Nam. Đây cũng là một di tích quốc gia đặc biệt của Việt Nam được xếp hạng đợt 4."},"den do":{"bai":"Đền Đô","t":"Đền Đô, tên chữ là Cổ Pháp điện, còn được gọi là Đền Lý Bát Đế, là một quần thể kiến trúc tín ngưỡng thờ tám vị vua đầu tiên của nhà Lý. Đền Đô đã được Nhà nước Việt Nam công nhận là di tích lịch sử - văn hóa theo Quyết định số 154 của Bộ Văn hóa – Thông tin (nay là Bộ Văn hóa, Thể thao và Du lịch) ngày 25 tháng 1 năm 1991."},"lang tranh dong ho":{"bai":"Tranh Đông Hồ","t":"Tranh Đông Hồ, hay tên đầy đủ là tranh khắc gỗ Đông Hồ, là một dòng tranh dân gian Việt Nam với xuất xứ từ làng Đông Hồ (phường Thuận Thành, thành phố Bắc Ninh). Trước kia tranh được bán ra chủ yếu phục vụ cho dịp Tết Nguyên Đán, người dân nông thôn mua tranh về dán trên tường, hết năm lại lột bỏ, dùng tranh mới."},"den ba chua kho":{"bai":"Đền Bà Chúa Kho","t":"Đền Bà Chúa Kho có thể là một trong số các ngôi đền sau: Đền Bà Chúa Kho (Việt Yên) thành phố Bắc Ninh thờ công chúa Thanh Bình (con vua Hùng), người trông coi lương thực theo truyền thuyết Thạch tướng quân đánh giặc. Đền Phủ, nơi tôn thờ bà chúa Kho thời Trần. Đền tọa lạc gần cuối đường Nguyễn Văn Cừ, phường Bắc Giang, thành phố Bắc Ninh."},"hoi lim":{"bai":"Hội Lim","t":"Hội Lim là một lễ hội lớn của thành phố Bắc Ninh, được tổ chức vào ngày 13 tháng giêng (13/1) hằng năm trên địa bàn phường Tiên Du. Hội Lim được coi là nét kết tinh độc đáo của vùng văn hoá Kinh Bắc."},"lang nghe duc dong dai bai":{"bai":"Làng nghề Việt Nam","t":"Làng nghề là một đơn vị hành chính cổ xưa mà cũng có nghĩa là một nơi quần cư đông người, sinh hoạt có tổ chức, có kỷ cương tập quán riêng theo nghĩa rộng. Làng nghề không những là một làng sống chuyên nghề mà cũng có hàm ý là những người cùng nghề sống hợp quần thể để phát triển công ăn việc làm."},"chua vinh nghiem":{"bai":"Chùa Vĩnh Nghiêm","t":"Chùa Vĩnh Nghiêm có thể chỉ: Chùa Vĩnh Nghiêm ở phường Tân An, thành phố Bắc Ninh. Chùa Vĩnh Nghiêm ở Thành phố Hồ Chí Minh. Chùa Vĩnh Nghiêm - Nürnberg - Cộng hòa liên bang Đức."},"den mau":{"bai":"Đền Mẫu","t":"Đền Mẫu có thể là một trong các công trình tín ngưỡng tại Việt Nam sau đây: Đền Mẫu Thoải (Đông Giang Linh Từ) tại ngõ 41 phố Trương Mỹ, phường Phạm Ngũ Lão, thành phố Hải Dương Đền Mẫu tại phường Phố Hiến, tỉnh Hưng Yên. Đền Mẫu tại phường Phố Hiến, tỉnh Hưng Yên. Đền Mẫu tại phường Lào Cai, thành phố Lào Cai, tỉnh Lào Cai. Đền Mẫu tại xã Hiền Lương, huyện Hạ Hòa, tỉnh Phú Thọ."},"chua chuong":{"bai":"Chùa Chuông","t":"Chùa Chuông, tên chữ là Kim Chung Tự , nằm tại thôn Nhân Dục, phường Hiến Nam, thành phố Hưng Yên (nay là phường phố Hiến, tỉnh Hưng Yên). Chùa Chuông nằm trong quần thể di tích Phố Hiến và được mệnh danh là \"Phố Hiến đệ nhất danh thắng\"."},"van mieu xich dang":{"bai":"Văn miếu Xích Đằng","t":"Văn miếu Xích Đằng hay còn gọi là Văn miếu Hưng Yên là một di tích quan trọng trong quần thể di tích Phố Hiến. Văn miếu Xích Đằng là văn miếu thuộc hàng tỉnh, được xây dựng vào khoảng năm 1701, hiện tại thuộc địa phận thôn Xích Đằng, phường Sơn Nam, tỉnh Hưng Yên. Văn miếu thờ Khổng Tử người sáng lập đạo Nho và thờ Vạn thế sư biểu Chu Văn An - nhà sư phạm tài năng đức độ thời Trần."},"den tran":{"bai":"Đền Trần","t":"Đền Trần, thường là tên gọi tắt các di tích thờ các vị vua nhà Trần hoặc Quốc công Trần Hưng Đạo. Đền Trần có thể gồm các đền thờ sau: Đền Trần, ở phường Nam Định tỉnh Ninh Bình. Đền Trần, Quảng Ninh hay Khu di tích nhà Trần tại Đông Triều, Quảng Ninh thờ các vua nhà Trần, còn gọi là Khu di tích lịch sử văn hóa Nhà Trần."},"dinh chua hien":{"bai":"Đình","t":"Đình là một công trình kiến trúc cổ truyền ở làng quê Việt Nam, là nơi thờ Thành hoàng, những người có công với đất nước, các anh hùng dân tộc và cũng là nơi hội họp của người dân trong cộng đồng. Ở miền Nam, những ngôi đình làng còn được gọi là \"Đình thần\"."},"den da trach":{"bai":"Đền Dạ Trạch","t":"Đền Dạ Trạch, còn gọi là Đền Hóa, là ngôi đền nằm ở thôn Yên Vĩnh, xã Triệu Việt Vương, tỉnh Hưng Yên, Việt Nam. Nơi đây thờ ba nhân vật trong truyền thuyết, gồm Chử Đồng Tử cùng nhị vị phu nhân là công chúa Tiên Dung và công chúa Hồng Vân (công chúa Tây Sa). Tương truyền đền được xây trên nền thành quách sau khi khi ba vị hóa về trời."},"chua thai lac":{"bai":"Chùa Thái Lạc","t":"Chùa Thái Lạc ở xã Như Quỳnh, tỉnh Hưng Yên. Chùa thuộc hệ thống chùa Tứ Pháp, thờ Phật và Pháp Vân. Chùa nổi tiếng vì có các bức chạm gõ từ đời Trần."},"chua keo":{"bai":"Chùa Keo","t":"Chùa Keo là tên gọi của một số ngôi chùa cổ ở Việt Nam. Một số ngôi chùa Keo cổ được biết đến nhiều nhất là: Chùa Keo Thái Bình, còn được gọi là chùa Keo Thượng, ở làng Dũng Nhuệ, xã Vũ Tiên, tỉnh Hưng Yên. Chùa Keo Hành Thiện, còn được gọi là chùa Keo Hạ hoặc Keo Hành Thiện, ở làng Hành Thiện, xã Xuân Hồng, tỉnh Ninh Bình."},"den tran thai binh":{"bai":"Trần Thái Tông","t":"Trần Thái Tông , 10 tháng 7 năm 1218 – 4 tháng 5 năm 1277) là vị hoàng đế đầu tiên của Hoàng triều Trần nước Đại Việt. Ông giữ ngôi từ ngày 10 tháng 1 năm 1226 tới ngày 30 tháng 3 năm 1258, sau đó làm Thái thượng hoàng cho đến khi qua đời năm 1277. Khi ông ra đời, cha ông là Trần Thừa đang là Phụ quốc Thái úy của nhà Lý do có công phò tá vua Huệ Tông trong loạn Quách Bốc."},"quan the trang an":{"bai":"Quần thể danh thắng Tràng An","t":"Quần thể danh thắng Tràng An là một vùng du lịch tổng hợp gồm các di sản văn hóa và thiên nhiên được UNESCO công nhận ở Ninh Bình, Việt Nam. Trước đó, nhiều di tích danh thắng nơi đây đã được Chính phủ Việt Nam xếp hạng di tích quốc gia đặc biệt quan trọng như Khu du lịch sinh thái Tràng An, khu du lịch Tam Cốc - Bích Động, chùa Bái Đính, cố đô Hoa Lư..."},"tam coc bich dong":{"bai":"Tam Cốc – Bích Động","t":"Tam Cốc – Bích Động là quần thể hang động ở phường Nam Hoa Lư, tỉnh Ninh Bình, Việt Nam. Tam Cốc – Bích Động còn được biết đến với những cái tên nổi tiếng như \"vịnh Hạ Long trên cạn\" hay \"Nam thiên đệ nhị động\" là một khu du lịch trọng điểm quốc gia Việt Nam. Toàn khu vực bao gồm hệ thống các hang động núi đá vôi và các di tích lịch sử liên quan đến hành cung Vũ Lâm của triều đại nhà Trần."},"hang mua":{"bai":"Hang Múa","t":"Hang Múa là hang trong núi đá vôi ở vùng đất thôn Khê Đầu Hạ phường Hoa Lư, tỉnh Ninh Bình, Việt Nam. Hang Múa nằm ở trung tâm tỉnh Ninh Bình, và cách Hà Nội khoảng 100 km. Hang Múa là một điểm du lịch nằm trong vùng lõi Quần thể di sản thế giới Tràng An, tỉnh Ninh Bình. Hang Múa có đặc điểm địa chất, địa mạo đặc trưng của vùng núi đá vôi có tuổi đời hàng triệu năm."},"co do hoa lu":{"bai":"Cố đô Hoa Lư","t":"Cố đô Hoa Lư là kinh đô của Việt Nam trong giai đoạn 968-1010. Đây là kinh đô đầu tiên của nhà nước phong kiến Trung ương tập quyền ở Việt Nam và là quê hương của vị Anh hùng dân tộc Đinh Bộ Lĩnh."},"chua bai dinh":{"bai":"Chùa Bái Đính","t":"Chùa Bái Đính là một quần thể chùa lớn với nhiều kỷ lục châu Á và Việt Nam được xác lập như chùa có tượng Phật bằng đồng dát vàng lớn nhất châu Á, chùa có hành lang La Hán dài nhất châu Á, có tượng Di lặc bằng đồng lớn nhất Đông Nam Á... Đây là ngôi chùa lớn nhất và sở hữu nhiều kỷ lục nhất ở Việt Nam."},"dam van long":{"bai":"Khu bảo tồn thiên nhiên đất ngập nước Vân Long","t":"Vân Long là khu bảo tồn thiên nhiên đất ngập nước lớn nhất vùng đồng bằng châu thổ Bắc Bộ. Khu bảo tồn này nằm ở vùng núi ngoài đê của 3 xã Gia Vân, Gia Viễn, Gia Hưng tỉnh Ninh Bình."},"thung nham":{"bai":"Khu du lịch sinh thái Thung Nham","t":"Khu du lịch sinh thái Thung Nham là một trong những tuyến điểm du lịch thuộc vùng lõi của quần thể di sản thế giới Tràng An. Vùng du lịch này nằm trong thung đồi Hải Nham, phường Nam Hoa Lư với điểm nhấn chính là đảo xem chim tự nhiên, rừng thực vật và các hang động như: động Vái Giời, động Tiên Cá, động Thủy Cung, hang Bụt,..."},"chua bich dong":{"bai":"Chùa Bích Động","t":"Chùa Bích Động là một ngôi chùa cổ được xây dựng trên dãy núi đá vôi Tràng An thuộc phường Nam Hoa Lư, tỉnh Ninh Bình. Đây là một di tích lịch sử văn hóa thuộc Quần thể danh thắng Tràng An Tam Cốc - Bích Động đã được xếp hạng di tích quốc gia đặc biệt và UNESCO công nhận là di sản thế giới."},"vuon quoc gia cuc phuong":{"bai":"Vườn quốc gia Cúc Phương","t":"Vườn Quốc gia Cúc Phương (hay rừng Cúc Phương) là một khu bảo tồn thiên nhiên, khu rừng đặc dụng nằm trên địa phận ranh giới 3 khu vực Đông Bắc Bộ, đồng bằng sông Hồng và Bắc Trung Bộ thuộc 3 tỉnh: Ninh Bình, Phú Thọ và Thanh Hóa. Vườn quốc gia này có hệ động thực vật phong phú đa dạng mang đặc trưng rừng mưa nhiệt đới."},"kenh ga":{"bai":"Suối nước nóng Kênh Gà","t":"Suối nước nóng Kênh Gà là suối nước nóng ở thôn Kênh Gà xã Gia Viễn tỉnh Ninh Bình, Việt Nam. Suối chảy ra từ lòng núi Kênh Gà ở làng nổi Kênh Gà và đổ vào nhánh sông Hoàng Long. Đây là một suối nước khoáng nổi tiếng, đã được Trung tâm sách kỷ lục Việt Nam đưa vào Top 5 khu du lịch suối nước nóng thu hút khách nhất ở Việt Nam."},"nha tho da phat diem":{"bai":"Nhà thờ chính tòa Phát Diệm","t":"Nhà thờ chính tòa Phát Diệm (thường gọi là Nhà thờ đá Phát Diệm) là một quần thể nhà thờ Công giáo rộng khoảng 22 ha, nằm tại thôn Phát Diệm, xã Phát Diệm, tỉnh Ninh Bình, cách Hà Nội khoảng 120 km về hướng Nam. Quần thể các công trình nơi đây được xây dựng từ năm 1875, đến năm 1899 thì hoàn thành."},"chua tam chuc":{"bai":"Khu du lịch Tam Chúc","t":"Tam Chúc là một khu du lịch quốc gia đồng thời cũng là danh thắng được xếp hạng di tích quốc gia đặc biệt ở phường Tam Chúc, tỉnh Ninh Bình, Việt Nam. Khu du lịch này có điểm nhấn là chùa Tam Chúc mới được nhiều báo chí Việt Nam coi là chùa lớn nhất thế giới. Quần thể Tam Chúc và Khu bảo tồn thiên nhiên đất ngập nước Vân Long đang được lập hồ sơ đề nghị UNESCO công nhận là di sản thế giới."},"den tran nam dinh":{"bai":"Đền Trần (Nam Định)","t":"Đền Trần là một quần thể đền thờ tại đường Trần Thừa, phường Nam Định, tỉnh Ninh Bình, Việt Nam. Từ phường Hoa Lư, trung tâm tỉnh Ninh Bình tới đền Trần 33 km. Đền nằm sát quốc lộ 10, là nơi thờ các vua Trần cùng các quan lại có công phù tá nhà Trần. Đền Trần được xây dựng từ năm 1695, trên nền Thái miếu cũ của nhà Trần đã bị quân Minh phá hủy vào thế kỷ XV."},"vuon quoc gia xuan thuy":{"bai":"Vườn quốc gia Xuân Thủy","t":"Vườn quốc gia Xuân Thủy là một vùng bãi bồi rộng lớn nằm ở phía Nam cửa sông Hồng, thuộc tỉnh Ninh Bình, cách Hà Nội khoảng 150 km về hướng Đông Nam, có tổng diện tích tự nhiên là 7.100 ha. Từ phường Hoa Lư, trung tâm tỉnh Ninh Bình tới vườn khoảng 75 km. Phù sa màu mỡ của sông Hồng và biển đã tạo dựng nên khu đất ngập nước với nhiều loài động thực vật hoang dã và các loài chim di cư quý hiếm."},"deo o quy ho":{"bai":"Đèo Ô Quý Hồ","t":"Đèo Ô Quý Hồ, đèo Ô Quy Hồ hay đèo Hoàng Liên Sơn là một ngọn đèo nằm trên quốc lộ 4D ở vùng giáp ranh giữa 2 tỉnh Lào Cai và Lai Châu, Việt Nam. Đèo cắt ngang dãy Hoàng Liên Sơn, với đỉnh đèo cũng ở gần ranh giới giữa 2 tỉnh. Tên chính thức của đèo ở đường phân thủy là \"đèo Trạm Tôn\". Đèo còn có tên địa phương còn là Cổng Trời."},"cau kinh rong may":{"bai":"Cầu kính Rồng Mây","t":"Cầu kính Rồng Mây (còn có tên gọi khác là cầu kính Sa Pa, cầu kính Ô Quý Hồ) là một cầu đi bộ trên cao nằm trong khuôn viên khu du lịch cầu kính Rồng Mây tọa lạc trên đèo Ô Quý Hồ thuộc xã Sơn Bình, huyện Tam Đường, tỉnh Lai Châu, Việt Nam. Đây là một phần trong tổng thể dự án có tổng vốn đầu tư 1.000 tỷ đồng, khởi công xây dựng vào năm 2017 và khánh thành cuối năm 2019."},"dinh pu ta leng":{"bai":"Pu Ta Leng","t":"Pu Ta Leng là một ngọn núi thuộc dãy Hoàng Liên Sơn, nằm trên địa phận hai tỉnh Lai Châu và Lào Cai thuộc vùng Tây Bắc Bộ, Việt Nam. Với chiều cao 3.049 m, đây là đỉnh núi cao thứ ba đã được khám phá ở Việt Nam. Tên núi có nguồn gốc từ tiếng H'Mông là \"Pú Tả Lèng\", trong đó \"Pú\" có nghĩa là núi."},"bao tang chien thang dien bien phu":{"bai":"Khu di tích chiến trường Điện Biên Phủ","t":"Quần thể di tích chiến trường Điện Biên Phủ là một quần thể các di tích lịch sử nằm tại tỉnh Điện Biên, ghi lại chiến công của Quân đội nhân dân Việt Nam trong chiến dịch Điện Biên Phủ. Đây là một trong 130 di tích quốc gia đặc biệt của Việt Nam. Quần thể bao gồm 46 di tích thành phần đã được công nhận và 4 di tích đề xuất bổ sung, trải rộng trên địa bàn 10 xã, phường của tỉnh Điện Biên."},"tuong dai chien thang dien bien phu":{"bai":"Tượng đài chiến thắng Điện Biên Phủ","t":"Tượng đài chiến thắng Điện Biên Phủ là một tượng đài để kỷ niệm sự kiện trận Điện Biên Phủ năm 1954 - là tượng đài bằng đồng lớn nhất Việt Nam hiện nay. Là một phần trong dự án trùng tu di tích lịch sử Điện Biên Phủ giai đoạn 1. Với tổng vốn đầu tư 47 tỷ đồng, trong đó phần xây lắp cơ sở hạ tầng 13 tỷ đồng."},"ho pa khoang":{"bai":"Hồ Pá Khoang","t":"Hồ Pá Khoang là một hồ chứa thủy lợi tại trung tâm tỉnh Điện Biên, Việt Nam. Khu vực này thuộc địa bàn xã Mường Phăng, cách trung tâm phường Điện Biên Phủ khoảng 20 km. Hồ nằm ở độ cao gần 900 m so với mực nước biển, diện mặt nước 600 ha và có dung tích 37,2 triệu m³ nước."},"so chi huy chien dich dien bien phu":{"bai":"Khu di tích chiến trường Điện Biên Phủ","t":"Quần thể di tích chiến trường Điện Biên Phủ là một quần thể các di tích lịch sử nằm tại tỉnh Điện Biên, ghi lại chiến công của Quân đội nhân dân Việt Nam trong chiến dịch Điện Biên Phủ. Đây là một trong 130 di tích quốc gia đặc biệt của Việt Nam. Quần thể bao gồm 46 di tích thành phần đã được công nhận và 4 di tích đề xuất bổ sung, trải rộng trên địa bàn 10 xã, phường của tỉnh Điện Biên."},"canh dong muong thanh":{"bai":"Đồng bằng Mường Thanh","t":"Đồng bằng Mường Thanh hay Đồng bằng Mường Then (theo tiếng dân tộc Thái nghĩa là Xứ Trời) là một đồng bằng nhỏ hẹp được tạo nên bởi phù sa của sông Nậm Rốm khi chảy qua một đứt gãy sâu, nằm trên địa bàn tỉnh Điện Biên, Việt Nam. Đồng bằng này dài 25 km và rộng từ 5 đến 6 km. Xung quanh Mường Thanh là có nhiều núi cao, khiến cho nó trở thành một thung lũng nằm giữa địa hình hiểm trở."},"cau muong thanh":{"bai":"Vụ Mường Thanh","t":"Vụ Mường Thanh là vụ tập đoàn xây dựng Mường Thanh bị điều tra tại 21 tỉnh, thành về những vị phạm có hệ thống với những dự án, công trình đồ sộ ngay giữa các đô thị, TP lớn, có dấu hiệu trốn thuế."},"thac dai yem":{"bai":"Thác Dải Yếm","t":"Thác Dải Yếm, còn gọi là thác Nàng, thác Bản Vặt, là thác trên suối Bó Sập tại phường Mộc Châu, tỉnh Sơn La. Tên gọi \"Dải Yếm\" liên quan đến truyền thuyết, kễ rằng thác là dải yếm của người con gái cứu chàng trai thoát khỏi dòng nước lũ."},"cau kinh bach long":{"bai":"Cầu kính Bạch Long","t":"Cầu kính Bạch Long là một cầu đi bộ sàn kính nằm trong khuôn viên khu du lịch Mộc Châu Island, thuộc phường Mộc Châu, tỉnh Sơn La. Được khởi công xây dựng vào năm 2021 với tổng vốn đầu tư 773 tỉ đồng, cầu mở cửa đón khách ngày 29 tháng 4 năm 2022 và được coi là cầu kính dài nhất thế giới vào thời điểm khánh thành."},"hang doi":{"bai":"Hang Dơi","t":"Hang Dơi là tên phổ biến đặt cho nhiều hang ở Việt Nam. Tên hình thành do có dơi đến sống hoặc từng sống trong hang đó. Hang Dơi Thanh Thủy ở xã Thanh Thủy, tỉnh Tuyên Quang. Hang Dơi Đức Hạnh ở bản Dình Phà, xã Cốc Pàng, tỉnh Cao Bằng. Hang DHang Dơi Hạ Lang, tiếng Nùng là Ngườm Ca Khào, ở xã Lý Quốc, tỉnh Cao Bằng, được xếp hạng là Di tích Danh lam thắng cảnh cấp quốc gia."},"ban cat cat":{"bai":"Bản Cát Cát","t":"Bản Cát Cát hay thôn Cát Cát là một làng dân tộc Mông thuộc xã Tả Van, tỉnh Lào Cai, Việt Nam, cách trung tâm thị xã 2 km. Đây là điểm tham quan hấp dẫn của du lịch Sa Pa nói riêng và Lào Cai nói chung. Bản Cát Cát là nơi tập trung đông đúc đồng bào dân tộc Mông sinh sống."},"nha tho da sa pa":{"bai":"Giáo xứ Sa Pa","t":"Giáo xứ Sapa thuộc giáo phận Hưng Hoá, nằm tại phường Sa Pa, tỉnh Lào Cai, thuộc vùng Tây Bắc Việt Nam, cách Hà Nội khoảng 400 km, cách Toà Giám mục giáo phận Hưng Hóa khoảng 360 km. Đây là một trong những giáo xứ xa nhất của giáo phận Hưng Hoá mà hầu hết giáo dân là người dân tộc H'Mông."},"nui ham rong":{"bai":"Núi Hàm Rồng","t":"Núi Hàm Rồng là tên núi, thuộc: Núi Hàm Rồng ở Sa Pa, tỉnh Lào Cai. Núi Hàm Rồng ở tỉnh Thanh Hóa. Núi Hàm Rồng ở tỉnh Gia Lai."},"thung lung muong hoa":{"bai":"Thung lũng Mường Hoa","t":"Thung lũng Mường Hoa là một thung lũng nằm trên địa bàn xã Tả Van, tỉnh Lào Cai, Việt Nam. Nơi đây được xem là khu vực có những ruộng bậc thang đẹp nhất, lớn nhất trong các ruộng bậc thang ở Sa Pa. Ruộng bậc thang nơi đây nằm uốn lượn quanh các sườn đồi, tạo thành hình chảo nghiêng tuyệt đẹp. Có lẽ bởi thế mà thung lũng Mường Hoa luôn được ví là nàng thơ của núi rừng Tây Bắc."},"thac bac":{"bai":"Thác Bạc","t":"Thác Bạc có thể đề cập đến các thắng cảnh sau: Thác Bạc (Sa Pa) ở phường Sa Pa, tỉnh Lào Cai. Thác Bạc Tam Đảo ở xã Tam Đảo tỉnh Phú Thọ. Thác Bạc Tú Sơn ở xóm Củ xã Mường Động, tỉnh Phú Thọ."},"thac tinh yeu":{"bai":"Thác Tình Yêu","t":"Thác Tình Yêu là một thắng cảnh tại khu du lịch Sa Pa, tỉnh Lào Cai. Thác nằm trên địa bàn của xã Tả Van, cách phường Sa Pa khoảng 14 km về hướng tây nam và cách đèo Ô Quy Hồ chừng 3 km theo đường thẳng. Thác Tình Yêu đồng thời cũng là điểm bắt đầu của hành trình Du lịch leo núi chinh phục đỉnh Fansipan, là đỉnh núi cao nhất Việt Nam."},"cho phien bac ha":{"bai":"Chợ phiên Bắc Hà","t":"Chợ Bắc Hà là một chợ phiên tại xã Bắc Hà, tỉnh Lào Cai, cách phường Lào Cai 65 km, khoảng 2 tiếng rưỡi đi bằng xe buýt. Chợ nổi tiếng vì còn giữ được vẻ nguyên sơ và mang đậm nét đặc trưng của các dân tộc vùng cao Việt Nam."},"dinh hoang a tuong":{"bai":"Dinh Hoàng A Tưởng","t":"Dinh Hoàng A Tưởng hay Lâu đài Hoàng Yến Tchao là công trình kiến trúc cổ do ông Hoàng Yến Tchao xây dựng ở xã Bắc Hà, tỉnh Lào Cai, Việt Nam. Dinh Hoàng A Tưởng được xây dựng từ năm 1914 và hoàn thành năm 1921, và gia đình ông Hoàng Yến Tchao sinh sống đến năm 1950."},"thac ban gioc":{"bai":"Thác Bản Giốc","t":"Thác Bản Giốc, phần phía Trung Quốc gọi là thác Đức Thiên , là một nhóm thác nước nằm trên sông Quây Sơn tại biên giới giữa Việt Nam và Trung Quốc."},"dong nguom ngao":{"bai":"Động Ngườm Ngao","t":"Động Ngườm Ngao hay Động Ngao là một hang động nằm ở bản Gun, xã Đàm Thủy, tỉnh Cao Bằng, Việt Nam. Động này toạ lạc trong lòng một quả núi, cách thác Bản Giốc 5 km. Động đã hình thành cách đây khoảng 300 năm, là một hang động trẻ so với nhiều hang khác ở Việt Nam. Nhiệt độ bên trong ổn định, dao động từ 18 đến 25 độ C, tạo điều kiện thuận lợi cho việc thăm thú các kỳ quan tự nhiên bên trong."},"khu di tich pac bo":{"bai":"Khu di tích Pác Bó","t":"Khu di tích Quốc gia đặc biệt Pác Bó (Khu di tích Chủ tịch Hồ Chí Minh tại Cao Bằng) là một khu di tích lịch sử cách mạng quốc gia - đặc biệt của Việt Nam, thuộc bản Pác Bó, xã Trường Hà, tỉnh Cao Bằng, cách phường Thục Phán 52 km về phía Bắc, là điểm đầu (km 0) của đường Hồ Chí Minh."},"ho thang hen":{"bai":"Hồ Thang Hen","t":"Hồ Thang Hen là một hồ nước ngọt tại xã Trà Lĩnh, tỉnh Cao Bằng, Việt Nam. Nó nằm ở độ cao trên 1000 mét so với mực nước biển, về phía bắc phường Thục Phán, cách cây số 34 trên đường từ phường Thục Phán về trung tâm xã Trà Lĩnh khoảng 5-7 km, Hồ nằm gần địa giới giữa xã Trà Lĩnh và xã Nguyễn Huệ."},"deo ma phuc":{"bai":"Đèo Mã Phục","t":"Đèo Mã Phục là đèo trên quốc lộ 3 ở vùng giáp ranh xã Nguyễn Huệ và Trà Lĩnh, tỉnh Cao Bằng, Việt Nam."},"suoi le nin":{"bai":"Suối Lê Nin","t":"Suối Lê Nin nay thuộc di tích lịch sử Pác Bó nằm trên địa bàn xã Trường Hà, tỉnh Cao Bằng, cách trung tâm phường Thục Phán 52 km về phía Bắc. Hồ Chí Minh sống và làm việc trong hang Cốc Bó và đặt tên dòng suối trước cửa hang là \"suối Lê Nin\" gắn với tên gọi là nhà cách mạng Nga là V.I.Lê Nin và ngọn núi có hang này là \"núi Các Mác\" là núi được đặt tên theo Nhà Cách Mạng Đức Các Mác."},"chua dong tam thanh":{"bai":"Chùa","t":"Chùa hay tự viện là một công trình kiến trúc phục vụ mục đích tín ngưỡng. Chùa được xây dựng phổ biến ở các nước Nam Á, Đông Á và Đông Nam Á, và nó thường là nơi thờ Phật. Tại nhiều nơi, chùa có nhiều điểm giống với chùa tháp của Ấn Độ, vốn là nơi cất giữ Xá-lị và chôn cất các vị đại sư, thường có nhiều tháp bao xung quanh."},"dinh mau son":{"bai":"Mẫu Sơn","t":"Mẫu Sơn là một dãy núi thuộc tỉnh Lạng Sơn, Việt Nam. Đây là một dãy núi cao chạy theo hướng đông – tây, nằm ở phía đông bắc tỉnh Lạng Sơn thuộc địa phận chính của 3 xã Ba Sơn, xã Công Sơn và xã Mẫu Sơn của tỉnh Lạng Sơn. Trung tâm dãy núi (khu du lịch hiện tại) cách thành phố Lạng Sơn 30 km theo đường bộ về phía đông. Đầu phía đông dãy núi giáp với biên giới Việt – Trung."},"ai chi lang":{"bai":"Chi Lăng","t":"Chi Lăng là một cửa ải nổi tiếng trong lịch sử Việt Nam. Nơi đây vốn là một thung lũng có sông Thương chảy qua, trải dài gần 20 km từ sông Hóa đến xã Nhân Lý, tỉnh Lạng Sơn. Phía đông thung lũng là dãy núi đất Thái Họa – Bảo Đài, còn phía tây là dãy núi đá Cai Kinh."},"thao nguyen huu lien":{"bai":"Ngôi nhà nhỏ trên thảo nguyên (phim truyền hình)","t":"Ngôi nhà nhỏ trên thảo nguyên (tiếng Anh: Little House on the Prairie) là một phim truyền hình do Michael Landon tổng đạo diễn, được xuất phẩm trong giai đoạn 1974—1983 trên sóng NBC."},"cua khau quoc te huu nghi":{"bai":"Cửa khẩu Hữu Nghị","t":"Cửa khẩu Quốc tế Hữu Nghị là một cửa khẩu quốc tế của tỉnh Lạng Sơn, Việt Nam nằm trên biên giới Việt Nam – Trung Quốc, điểm nối tuyến đường cao tốc Nam Ninh – Hà Nội, là cầu nối quan trọng trong phát triển quan hệ kinh tế giữa Việt Nam và Trung Quốc. Tại cửa khẩu Hữu Nghị, Việt Nam đã cắm cột mốc 1116 có gắn quốc huy của 2 nước."},"den ky cung":{"bai":"Đền Kỳ Cùng","t":"Đền Kỳ Cùng (còn có tên là đền Quan Lớn Tuần Tranh) nằm bên tả ngạn sông Kỳ Cùng và ở ngay đầu cầu Kỳ Cùng; hiện thuộc địa phận phường Đông Kinh, tỉnh Lạng Sơn, Việt Nam. Năm 1993, ngôi đền đã được xếp hạng là di tích Lịch sử - Văn hóa cấp quốc gia."},"thung lung bac son":{"bai":"Thung lũng","t":"Thung lũng, hoặc gọi là lũng, khe, là địa hình âm hẹp và dài do hai bên địa hình dương kẹp chặt và đứng đối mặt với nhau, thường có sự phát triển của chi lưu, dòng sông và hồ chằm, thung lũng dốc gần như thẳng đứng có khả năng có dòng bùn đá, ở trên bản đồ địa hình đường đẳng cao biểu hiện là một nhóm đường đẳng cao nhô ra hướng về phía chỗ cao."},"khu di tich lich su den hung":{"bai":"Đền Hùng","t":"Đền Hùng (Tên chữ: Hùng Vương miếu) là tên gọi khái quát của Khu di tích lịch sử Đền Hùng - quần thể đền chùa thờ phụng các Vua Hùng và tôn thất của nhà vua trên núi Nghĩa Lĩnh, xã Hy Cương, tỉnh Phú Thọ, xưa thuộc xã Hy Cương, huyện Sơn Vi, gắn với Giỗ Tổ Hùng Vương - Lễ hội Đền Hùng được tổ chức tại địa điểm đó hàng năm vào ngày 10 tháng 3 âm lịch."},"bao tang hung vuong":{"bai":"Hùng Vương","t":"Hùng Vương hay vua Hùng là cách gọi dành cho các vị vua nước Văn Lang của người Lạc Việt, tồn tại vào khoảng thế kỷ VII đến thế kỷ II trước Công nguyên. Theo truyền thuyết, Hùng Vương có tổng 18 đời vua."},"vuon quoc gia xuan son":{"bai":"Vườn quốc gia Xuân Sơn","t":"Vườn quốc gia Xuân Sơn là một vườn quốc gia nằm trên địa bàn xã Xuân Đài và Lai Đồng, tỉnh Phú Thọ. Với kiểu địa hình núi đá vôi đặc trưng. Được chuyển từ khu bảo tồn thiên nhiên Xuân Sơn thành vườn quốc gia theo Quyết định của Thủ tướng chính phủ Cộng hòa xã hội chủ nghĩa Việt Nam số 49/2002/QĐ-TTg ngày 17 tháng 4 năm 2002."},"dam ao chau":{"bai":"Đầm Ao Châu","t":"Đầm Ao Châu nằm trên địa bàn xã Hạ Hòa và xã Đan Thượng trực thuộc tỉnh Phú Thọ, cách phường Phú Thọ 35 km, cách phường Việt Trì 60 km. Đầm Ao Châu được coi là một Hạ Long trên đất Phú Thọ."},"den quoc to lac long quan":{"bai":"Lạc Long Quân","t":"Lạc Long Quân , tên húy là Sùng Lãm , là một vị vua truyền thuyết của lịch sử Việt Nam. Theo Đại Việt Sử ký Toàn thư thì cha ông là Kinh Dương Vương Lộc Tục và mẹ ông là Thần Long - con gái của Động Đình Quân. Lạc Long Quân được xem là vị vua của nhà nước sơ khai Xích Quỷ trước nhà nước Văn Lang."},"den mau au co":{"bai":"Đền Mẫu Âu Cơ","t":"Đền mẫu Âu Cơ là nơi thờ Mẹ Âu Cơ, được xây dựng từ thời Hậu Lê, nằm trên địa phận xã Hiền Lương, tỉnh Phú Thọ, Việt Nam."},"hang phuong hoang suoi mo ga":{"bai":"Hang Phượng Hoàng - suối Mỏ Gà","t":"Hang Phượng Hoàng - Suối Mỏ Gà là một khu thắng cảnh du lịch nổi tiếng của tỉnh Thái Nguyên. Hang Phượng Hoàng nằm trên núi Phượng Hoàng thuộc xã Võ Nhai, cách phường Phan Đình Phùng 45 km và nằm rất gần quốc lộ 1B (Thái Nguyên - Lạng Sơn) ở vị trí sát ranh giới giữa hai tỉnh."},"thac khuon tat":{"bai":"Thác Khuôn Tát","t":"Thác Khuôn Tát là thác trên suối thượng nguồn sông Công ở vùng đất xóm Tỉn Keo xã Phú Đình, tỉnh Thái Nguyên. Thác Khuôn Tát thuộc khu vực di tích lịch sử ATK Định Hóa, là trung tâm căn cứ địa Việt Bắc và đại bản doanh lãnh đạo cuộc kháng chiến trường kỳ do chủ tịch Hồ Chí Minh lãnh đạo trong chiến tranh Đông Dương (1946-1954). Thác Khuôn Tát được xếp hạng danh thắng cấp quốc gia vào năm 2002."},"bao tang van hoa cac dan toc viet nam":{"bai":"Bảo tàng Văn hóa các Dân tộc Việt Nam","t":"Bảo tàng văn hoá các dân tộc Việt Nam là một thiết chế văn hoá được xây dựng từ năm 1960, nằm tại phường Phan Đình Phùng, tỉnh Thái Nguyên, cách thủ đô Hà Nội hơn 80 km về phía Bắc."},"ho ba be":{"bai":"Hồ Ba Bể","t":"Hồ Ba Bể là một hồ nước ngọt ở Thái Nguyên, Việt Nam. Đây là hồ nước ngọt tự nhiên lớn nhất Việt Nam và là một trong một trăm hồ nước ngọt lớn nhất thế giới. Hồ nằm trong Vườn quốc gia Ba Bể, nơi đây được công nhận là khu du lịch quốc gia Việt Nam."},"den duom":{"bai":"Đền Đuổm","t":"Đền Đuổm là ngôi đền thờ Dương Tự Minh (Thánh Đuổm) còn gọi là Đức Thánh Đuổm hay Cao Sơn Quý Minh - một vị tướng người Tày, phò mã nhà Lý, đã có nhiều công trạng. Người dân tộc Tày, người làng Quán Triều, phủ Phú Lương, tỉnh Thái Nguyên (nay là phường Quan Triều, tỉnh Thái Nguyên)."},"dong hua ma":{"bai":"Động Hua Mạ","t":"Động Hua Mạ là một thắng cảnh thuộc khu vực vườn quốc gia Ba Bể. Hang nằm bên dòng sông Lèng và thuộc bản Pắc Ngòi, xã Đồng Phúc, tỉnh Thái Nguyên. Động Hua Mạ nằm ở lưng chừng ngọn núi Cô Đơn nằm giữa khu Lèo Pèn (Rừng Ma) cây cối xanh rì, rậm rạp. Động Hua Mạ ăn sâu vào lòng núi theo hướng Đông - Nam quanh năm u tịch và được người dân bản địa gọi là hang Lèo Pèn."},"thac dau dang":{"bai":"Thác Đầu Đẳng","t":"Thác Đầu Đẳng là một thắng cảnh trong khu vực Vườn quốc gia Ba Bể, xã Ba Bể, tỉnh Thái Nguyên, Việt Nam. Thác Đầu Đẳng nằm trên dòng sông Năng, ở nơi giáp ranh giữa tỉnh Thái Nguyên với tỉnh Tuyên Quang. Thác cách xã Chợ Rã khoảng 16 km. Sông Năng sau khi luồn dưới núi đá vôi Lũng Nham tạo thành động Puông khi chảy đến bản Húa Tạng thì bị hàng trăm tảng đá lớn chặn lại tạ thành dòng thác."},"khu di tich lich su tan trao":{"bai":"Chiến khu Tân Trào","t":"Chiến khu Tân Trào là khu di tích lịch sử của cách mạng Việt Nam thời kỳ Cách mạng tháng Tám. Hiện nay, nơi đây đã được thủ tướng chính phủ Việt Nam đưa vào danh sách xếp hạng 130 di tích quốc gia đặc biệt. Tân Trào là thủ đô lâm thời của khu giải phóng, nơi Đảng Cộng sản Việt Nam tiến hành hội nghị toàn quốc ngày 13 tháng 8 năm 1945 để quyết định tổng khởi nghĩa."},"thac ban ba":{"bai":"Thác Bản Ba","t":"Thác Bản Ba là thác trên dòng ngòi Ba ở vùng đất Bản Ba, xã Trung Hà tỉnh Tuyên Quang, Việt Nam. Thác có 3 tầng, ở độ cao địa hình cỡ 170 m, ở cách Tuyên Quang 70 km. Từ Chiêm Hóa đi 25 km đến Bản Ba, và đi bộ cỡ 1 km đến thác. Vùng thác là điểm sinh thái đã được nhà nước công nhận là danh thắng cấp quốc gia năm 2007, và là điểm đến hấp dẫn của nhiều du khách trong nước và quốc tế."},"suoi khoang my lam":{"bai":"Suối nước khoáng Mỹ Lâm","t":"Suối nước khoáng Mỹ Lâm thuộc phường Mỹ Lâm, tỉnh Tuyên Quang. Suối khoáng Mỹ Lâm còn có tên gọi khác là \"Suối khoáng Sun-phua\" do hàm lượng Hydro sulfide trong nước lên đến 5 mg/lít. Nguồn nước được các nhà địa chất học người Pháp phát hiện từ năm 1923."},"thanh nha mac":{"bai":"Thành nhà Mạc","t":"Thành nhà Mạc có thể là: Thành nhà Mạc ở phường Tam Thanh, tỉnh Lạng Sơn, Việt Nam. Thành cổ Phục Hòa ở xã Phục Hòa, tỉnh Cao Bằng, Việt Nam. Thành cổ Nà Lữ ở phường Thục Phán, tỉnh Cao Bằng, Việt Nam. Thành cổ Tuyên Quang ở phường Minh Xuân, tỉnh Tuyên Quang, Việt Nam. Thành nhà Mạc ở xã Cao Dương, tỉnh Phú Thọ, Việt Nam."},"dong song long":{"bai":"Tiền đồ lớn lao: Song long hội","t":"Tiền đồ lớn lao: Song long hội là một bộ phim hành động võ thuật Trung Quốc sản xuất năm 2018 lấy bối cảnh xã hội Thiên Tân những năm 1925 khi Trung Hoa Dân quốc vẫn còn kiểm soát Hoa Lục."},"bai bien sam son":{"bai":"Bãi biển Sầm Sơn","t":"Bãi biển Sầm Sơn là một trong những bãi biển đẹp nhất Việt Nam và luôn là bãi biển đông khách nhất miền Bắc, Việt Nam. Bãi biển thuộc phường Sầm Sơn, tỉnh Thanh Hóa. Bờ biển cách thành phố Thanh Hóa cũ 16 km về phía Đông, cách Hà Nội 164 km tương đương 2,5 giờ đi xe."},"thanh nha ho":{"bai":"Thành nhà Hồ","t":"Thành nhà Hồ (hay còn gọi là thành Tây Đô, thành An Tôn, thành Tây Kinh hay thành Tây Giai) là kinh đô nước Đại Ngu (quốc hiệu Việt Nam dưới thời nhà Hồ), nằm trên địa phận tỉnh Thanh Hóa."},"khu di tich lam kinh":{"bai":"Lam Kinh","t":"Khu di tích lịch sử Lam Kinh cách phường Hạc Thành 50 km về phía Tây Bắc, nằm trên địa bàn xã Lam Sơn, tỉnh Thanh Hóa. Đây là một di tích lịch sử quốc gia cấp từ năm 1962. Năm 2012, khu di tích này được công nhận là di tích quốc gia đặc biệt. Nhân vật tạo lập Lam Kinh là Lê Thái Tổ."},"khu bao ton thien nhien pu luong":{"bai":"Khu bảo tồn thiên nhiên Pù Luông","t":"Khu bảo tồn thiên nhiên Pù Luông thuộc địa phận các huyện Bá Thước và Quan Hóa, nằm ở phía tây bắc tỉnh Thanh Hóa, Việt Nam, cách thành phố Thanh Hóa 130 km và cách Thị Trấn Cành Nàng khoảng chừng 20 km về phía tây bắc, cách Hà Nội khoảng 178 km về phía Tây Nam."},"suoi ca than cam luong":{"bai":"Suối Cá thần","t":"Suối Cá Cẩm Thủy là một dòng suối ở miền núi phía Tây tỉnh Thanh Hóa, Việt Nam, nơi có những đàn cá tập trung sinh sống với mật độ dày đặc, được đồng bào dân tộc Mường, Thái ở địa phương gìn giữ và đã trở thành những danh lam thắng cảnh nổi tiếng của tỉnh Thanh Hóa."},"vuon quoc gia ben en":{"bai":"Vườn quốc gia Bến En","t":"Vườn quốc gia Bến En là một vườn quốc gia thuộc tỉnh Thanh Hóa, Việt Nam. Được thành lập theo quyết định số 33 ngày 27 tháng 1 năm 1992 của Chủ tịch Hội đồng Bộ trưởng Việt Nam."},"den ba trieu":{"bai":"Đền Bà Triệu","t":"Đền Bà Triệu là nơi thờ tự vị nữ anh hùng dân tộc Việt tên là Triệu Thị Trinh, người đã có công đánh đuổi quân xâm lược Đông Ngô (Trung Quốc) vào giữa thế kỷ thứ 3. Đền nằm trên núi Gai, ngay sát Quốc lộ 1, đoạn đi qua thôn Phú Điền, xã Triệu Lộc, tỉnh Thanh Hóa, cách thành phố Thanh Hóa 18 km về phía Bắc và cách Hà Nội 137 km về phía Nam."},"thac hieu":{"bai":"Thác Hiêu","t":"Thác Hiêu là thác ở vùng đất bản Hiêu xã Cổ Lũng, tỉnh Thanh Hóa, Việt Nam. Thác Hiêu nằm trong vùng lõi Khu bảo tồn thiên nhiên Pù Luông, giáp ranh với tỉnh Phú Thọ. Suối Bản Hiêu bắt nguồn từ dãy núi đá vôi của khu bảo tồn, có thủy vực rộng và nhiều vị trí chảy ngầm qua hang karst. Chiều dài dòng thác khoảng 800 m."},"bai bien cua lo":{"bai":"Bãi biển Cửa Lò","t":"Bãi biển Cửa Lò là một trong những bãi biển đẹp ở Bắc Trung Bộ Việt Nam. Bãi biển này thuộc phường Cửa Lò, tỉnh Nghệ An, cách trung tâm thành phố Vinh 16 km về phía Đông Bắc, cách thủ đô Hà Nội 288 km, và cách Thành phố Hồ Chí Minh 1402 km. Cửa Lò cũng được nối với Lào và Bắc Thái Lan bởi Quốc lộ 8 và cách Viêng Chăn thủ đô của Lào 468 km."},"khu di tich kim lien":{"bai":"Khu di tích lịch sử Kim Liên","t":"Khu di tích lịch sử Kim Liên (Khu di tích Chủ tịch Hồ Chí Minh tại Nghệ An) là khu di tích tưởng niệm chủ tịch Hồ Chí Minh tại xã Kim Liên, tỉnh Nghệ An thuộc vùng duyên hải miền Trung Việt Nam, cách phường Trường Vinh 12 km theo quốc lộ 46 . Hiện nay, nơi đây đã được thủ tướng chính phủ Việt Nam đưa vào danh sách xếp hạng 23 di tích quốc gia đặc biệt."},"vuon quoc gia pu mat":{"bai":"Vườn quốc gia Pù Mát","t":"Vườn quốc gia Pù Mát là một khu rừng đặc dụng ở phía tây tỉnh Nghệ An. Tiếng Thái, Pù Mát có nghĩa là những con dốc cao. Được thành lập theo quyết định số 174/2001/QĐ-TTg của Thủ tướng Chính phủ ngày 08/11/2001 về việc chuyển hạng Khu Bảo tồn Thiên nhiên Pù Mát thành Vườn quốc gia."},"thanh co vinh":{"bai":"Thành Nghệ An","t":"Thành cổ Nghệ An, còn gọi là Thành cổ Vinh, là tên gọi di tích một tòa thành cổ được xây dựng dưới thời Nguyễn lịch sử Việt Nam, nằm trên địa bàn phường Thành Vinh, tỉnh Nghệ An ngày nay. Hiện tòa thành cổ này vẫn còn di tích 3 cổng thành là Tiền môn, Tả môn, Hữu môn và một số đoạn hào thành. Di tích thành cổ Nghệ An được nhà nước Việt Nam xếp hạng Di tích lịch sử Quốc gia năm 1998."},"den cuong":{"bai":"Đền Cuông","t":"Đền Cuông là một trong những ngôi đền thờ An Dương Vương Thục Phán, tọa lạc trên núi Mộ Dạ thuộc xã An Châu, tỉnh Nghệ An."},"chua huong tich":{"bai":"Chùa Hương Tích","t":"Chùa Hương Tích (tên chữ: Hương Tích Cổ Tự; tên dân gian: chùa Thơm) là ngôi chùa nằm tại đỉnh Hương Tích thuộc dãy núi Hồng Lĩnh ở xã Thiên Lộc huyện Can Lộc tỉnh Hà Tĩnh với độ cao 650m so với mực nước biển. Lễ chính của chùa diễn ra vào ngày 18 tháng 2 âm lịch, nơi đây thờ Quan Âm Bồ Tát."},"ho ke go":{"bai":"Hồ Kẻ Gỗ","t":"Hồ Kẻ Gỗ (Công trình Thủy lợi Kẻ Gỗ) là một hồ nước nhân tạo tại xã Cẩm Duệ, tỉnh Hà Tĩnh. Kẻ Gỗ là hồ lớn nhất ở Hà Tĩnh. Hồ Kẻ Gỗ là một công trình nhân tạo mang tính chất phục vụ thủy lợi là chính, hồ được xây dựng trên lưu vực của sông Rào Cái. Hồ được khởi công xây dựng từ năm 1976 tới năm 1980 thì hoàn thành các hạng mục chính, đến năm 1983 thì toàn bộ hệ thống được đưa vào sử dụng."},"nui hong linh":{"bai":"Dãy núi Hồng Lĩnh","t":"Dãy núi Hồng Lĩnh là một dãy núi nằm tại tỉnh Hà Tĩnh. Dãy núi Hồng Lĩnh cùng với sông Lam là địa danh mang tính biểu tượng của Xứ Nghệ (hai tỉnh Nghệ An và Hà Tĩnh hiện nay). Đây còn là một trong 9 ngọn núi được khắc vào Cửu Đỉnh ở Cố đô Huế (9 đỉnh đồng tại Kinh thành Huế)."},"deo ngang":{"bai":"Đèo Ngang","t":"Đèo Ngang là đèo trên Quốc lộ 1 cũ vượt núi Hoành Sơn tại ranh giới của 2 tỉnh Hà Tĩnh và Quảng Trị. Đèo Ngang là một thắng cảnh của miền Trung Việt Nam, nổi tiếng qua bài thơ Qua Đèo Ngang của Bà Huyện Thanh Quan. Từ năm 2004 Hầm đường bộ Đèo Ngang được xây dựng, thay thế đoạn đường đèo vượt núi Hoành Sơn. Đèo Ngang có độ cao 250 m so với mực nước biển."},"cang vung ang bien ky xuan":{"bai":"Cảng Sơn Dương – Vũng Áng","t":"Cảng Sơn Dương – Vũng Áng là một cảng tổng hợp quốc gia, đầu mối khu vực (cảng loại I) của Việt Nam, nằm trong vũng Áng thuộc phường Vũng Áng, tỉnh Hà Tĩnh, cách Quốc lộ 1 chỉ 9 km, cách biên giới Việt Nam - Lào (đèo Mụ Giạ) khoảng 230 km."},"thanh co quang tri":{"bai":"Thành cổ Quảng Trị","t":"Thành cổ Quảng Trị hoặc Cổ thành Quảng Trị là một Di tích quốc gia đặc biệt của Việt Nam được xếp hạng đợt 4, tọa lạc ở trung tâm phường Quảng Trị, tỉnh Quảng Trị. Theo tài liệu thì vào đầu thời Gia Long, thành Quảng Trị được xây dựng tại phường Tiền Kiên (Triệu Thành - Triệu Phong), đến năm 1809, vua Gia Long cho dời đến xã Thạch Hãn (tức vị trí ngày nay, thuộc phường 2, thị xã Quảng Trị)."},"dia dao vinh moc":{"bai":"Địa đạo Vịnh Mốc","t":"Địa đạo Vịnh Mốc (thôn Vịnh Mốc, xã Cửa Tùng, tỉnh Quảng Trị) là một công trình quân - dân sự trong Chiến tranh Việt Nam của phía Việt Nam Dân chủ Cộng hòa nhằm chống lại các cuộc tấn công của phía Việt Nam Cộng hòa và Hợp chúng quốc Hoa Kỳ. Hệ thống địa đạo tồn tại ở phía Bắc sông Bến Hải, cầu Hiền Lương trong suốt những năm 1965-1972."},"cau hien luong song ben hai":{"bai":"Cầu Hiền Lương","t":"Cầu Hiền Lương bắc qua sông Bến Hải, tại thôn Hiền Lương, xã Cửa Tùng, tỉnh Quảng Trị, Việt Nam. Cũng tại nơi đây, đã từng diễn ra những cuộc \"chọi loa\", \"chọi cờ\" quyết liệt trong Chiến tranh Việt Nam."},"can cu khe sanh san bay ta con":{"bai":"Sân bay Tà Cơn","t":"Sân bay Tà Cơn hiện là một di tích lịch sử ở vùng đất thôn Hòa Thành, xã Khe Sanh, tỉnh Quảng Trị, Việt Nam. Trong Chiến tranh Việt Nam thời kỳ năm 1966 – 1968 sân bay Tà Cơn là đầu cầu hàng không trong cụm cứ điểm quân sự chiến lược của quân đội Mỹ, là mắt xích quan trọng của tập đoàn cứ điểm Khe Sanh."},"nghia trang liet si quoc gia truong son":{"bai":"Nghĩa trang liệt sĩ Trường Sơn","t":"Nghĩa trang liệt sĩ Trường Sơn là nơi quy tập phần mộ các liệt sĩ của Quân Giải phóng miền Nam Việt Nam và Quân đội Nhân dân Việt Nam, trên tuyến đường Trường Sơn – còn được gọi là đường mòn Hồ Chí Minh."},"bien cua tung":{"bai":"Bãi biển Cửa Tùng","t":"Bãi biển Cửa Tùng thuộc xã Cửa Tùng, tỉnh Quảng Trị. Bãi biển Cửa Tùng giáp với Địa đạo Vĩnh Mốc và sông Bến Hải chảy ra biển tạo nên bãi tắm Cửa Tùng. Bãi biển này được người Pháp mệnh danh là \"Nữ hoàng của các bãi biển\" vì bãi cát mịn với những ngầm đá nhô ra biển."},"dao con co":{"bai":"Cồn Cỏ","t":"Cồn Cỏ là một đặc khu thuộc tỉnh Quảng Trị, Việt Nam. Tên đặc khu được kế thừa cho huyện đảo Cồn Cỏ trước đây."},"cau dakrong thac chenh venh":{"bai":"Cầu Đakrông","t":"Cầu Đakrông là một cây cầu bắc qua sông Đakrông trên tuyến đường Hồ Chí Minh tại xã Đakrông, tỉnh Quảng Trị, Việt Nam. Cầu nằm trong khu di tích - danh thắng Đakrông. Đây là điểm đầu của Quốc lộ 14 nối từ Quảng Trị đến Đồng Nai. Trong chiến tranh, cầu Đakrông là một chiếc cầu sắt và là tuyến vận tải quan trọng cho chiến trường miền Nam."},"cho dong ha":{"bai":"Chợ Đông Hà","t":"Chợ Đông Hà là một ngôi chợ nằm ở trung tâm phường Đông Hà, tỉnh Quảng Trị, Việt Nam. Đây là chợ có quy mô lớn nhất tỉnh Quảng Trị. Chợ nằm bên cạnh sông Hiếu, có nét kiến trúc đặc trưng gợi hình tượng những con thuyền đang đậu sát vào nhau. Hiện nay, chợ còn là nơi phục vụ du khách các loại hàng hóa có nguồn gốc từ Thái Lan, Trung Quốc và Lào, chủ yếu được nhập về thông qua cửa khẩu Lao Bảo."},"cong vien fidel castro":{"bai":"Fidel Castro","t":"Fidel Alejandro Castro Ruz (phiên âm tiếng Việt: Phi-đen Cát-xtơ-rô; 13 tháng 8 năm 1926 – 25 tháng 11 năm 2016) là một nhà cách mạng và chính trị gia người Cuba, một trong những nhà lãnh đạo chủ chốt của Cách mạng Cuba, Thủ tướng Cuba từ tháng 2 năm 1959 đến tháng 12 năm 1976 và sau đó là Chủ tịch Hội đồng Nhà nước Cuba đến khi ông từ chức tháng 2 năm 2008."},"chua thien mu":{"bai":"Chùa Thiên Mụ","t":"Chùa Thiên Mụ hay còn gọi là chùa Linh Mụ là một ngôi chùa cổ nằm trên đồi Hà Khê, tả ngạn sông Hương, cách trung tâm thành phố Huế (Việt Nam) khoảng 5 km về phía tây. Chùa Thiên Mụ chính thức khởi lập năm Tân Sửu (1601), đời chúa Tiên Nguyễn Hoàng - vị chúa Nguyễn đầu tiên ở Đàng Trong."},"lang khai dinh":{"bai":"Lăng Khải Định","t":"Lăng Khải Định, còn gọi là Ứng Lăng là lăng tẩm của Hoàng đế Khải Định (1885-1925), vị Hoàng đế thứ 12 Triều Nguyễn. Lăng tọa lạc tại núi Châu Chữ, phường Thủy Xuân, thành phố Huế. Công trình kiến trúc này nằm trong quần thể di tích cố đô Huế, di sản thế giới đã được UNESCO công nhận từ năm 1993."},"lang tu duc":{"bai":"Lăng Tự Đức","t":"Lăng Tự Đức là một quần thể Di tích công trình kiến trúc, trong đó có nơi chôn cất Tự Đức, tọa lạc trong một thung lũng hẹp thuộc làng Dương Xuân Thượng, tổng Cư Chánh, nay là tổ dân phố Thượng Ba, phường Thủy Xuân, thành phố Huế. Lúc mới xây dựng, Tự Đức đặt tên là Khiêm Cung . Sau khi Tự Đức băng hà, lăng được đổi tên thành Khiêm Lăng ."},"lang minh mang":{"bai":"Lăng Minh Mạng","t":"Lăng Minh Mạng (hay còn gọi là Minh Mệnh) có tên chữ là Hiếu lăng , do hoàng đế Thiệu Trị thời nhà Nguyễn cho xây dựng, nằm trên núi Cẩm Kê, ấp An Bằng, phường Kim Long, thành phố Huế, gần ngã ba Bằng Lãng là nơi hội lưu của hai dòng Hữu Trạch và Tả Trạch hợp thành sông Hương, cách trung tâm thành phố Huế 12 km."},"cung an dinh":{"bai":"Cung An Định","t":"Cung An Định tọa lạc bên bờ sông An Cựu, xưa thuộc phường Đệ Bát, thị xã Huế (nay tại số 179 đường Phan Đình Phùng, phường Thuận Hóa, thành phố Huế) là cung điện riêng của vua Khải Định từ khi còn là thái tử đến khi làm vua, sau này được Bảo Đại thừa kế và từng sống ở đây sau khi thoái vị."},"cho dong ba":{"bai":"Chợ Đông Ba","t":"Chợ Đông Ba là một ngôi chợ tại thành phố Huế, Việt Nam. Đây là ngôi chợ truyền thống lâu đời, có lịch sử hơn 100 năm xây dựng và phát triển, được xem là một trong những biểu tượng của vùng đất cố đô Huế."},"cau truong tien song huong":{"bai":"Cầu Trường Tiền","t":"Cầu Trường Tiền hay cầu Tràng Tiền là chiếc cầu dài 402,60 m, gồm 6 nhịp dầm thép hình vành lược, khẩu độ mỗi nhịp 67 m. Khổ cầu 6 m, được thiết kế theo kiến trúc Gothic, bắc qua sông Hương, thuộc đoạn Quốc lộ 1 cũ cho đến khi cầu Phú Xuân thay thế vai trò. Đầu cầu phía bắc thuộc phường Phú Xuân; đầu cầu phía nam thuộc phường Thuận Hóa, thành phố Huế, Việt Nam."},"lang huong thuy xuan":{"bai":"Hồ Xuân Hương","t":"Hồ Xuân Hương là một nữ thi sĩ người Việt Nam sống ở giai đoạn cuối thế kỷ XVIII và đầu thế kỷ XIX, mà hiện tại vẫn khiến nhiều học giả tranh cãi. Bà được nhà thơ hiện đại Xuân Diệu mệnh danh là Bà chúa thơ Nôm. Năm 2021, bà cùng Nguyễn Đình Chiểu là hai nhà thơ của Việt Nam được UNESCO vinh danh là \"danh nhân văn hóa thế giới\" cùng với kỷ niệm năm sinh/năm mất."},"bien thuan an":{"bai":"Bãi biển Thuận An","t":"Bãi biển Thuận An là một bãi biển thuộc phường Thuận An, quận Thuận Hóa, thành phố Huế, biển nằm ngay bên cạnh cửa biển Thuận An. Cùng với biển Lăng Cô, phá Tam Giang thì biển Thuận An cũng chính là một kiệt tác của thiên nhiên ở Huế thu hút du khách mọi miền. Đây chính là nơi sông Hương xuôi dòng hướng phá Tam Giang rồi đổ ra biển Đông, hòa cùng đại dương mênh mang."},"dien hon chen":{"bai":"Điện Hòn Chén","t":"Điện Hòn Chén hay Huệ Nam Điện tọa lạc trên núi Ngọc Trản, phường Kim Long, thành phố Huế. Núi Ngọc Trản xưa có tên là Hương Uyển Sơn, sau mới đổi tên là Ngọc Trản (có nghĩa là chén ngọc), dân gian vẫn quen gọi là Hòn Chén vì nó có liên quan đến giai thoại về vua Minh Mạng đánh rơi chén ngọc."},"chua huyen khong son thuong":{"bai":"Huyền Không Sơn Thượng","t":"Huyền Không Sơn Thượng là một ngôi chùa ở thôn Chầm, phường Kim Long, thành phố Huế. Chùa thuộc hệ phái Phật giáo Nam tông, được Hoà thượng Giới Đức khai sơn năm 1989. Chùa nổi tiếng với bài thơ Đá của Huyền Không Sơn Thượng Triều Tâm Ảnh và Sấu Mã."},"pha tam giang":{"bai":"Phá Tam Giang","t":"Phá Tam Giang là một phá nằm trong hệ đầm phá Tam Giang - Cầu Hai. Diện tích phá Tam Giang khoảng 52 km², trải dài khoảng 24 km theo hướng tây tây bắc-đông đông nam từ cửa sông Ô Lâu đến cửa sông Hương, thuộc địa phận hai quận Phú Xuân, Thuận Hóa, thị xã Phong Điền và huyện Quảng Điền thuộc thành phố Huế. Tọa độ trung tâm phá khoảng ."},"ngu hanh son":{"bai":"Ngũ Hành Sơn","t":"Ngũ Hành Sơn là một danh thắng gồm 6 ngọn núi đá vôi nhô lên trên một bãi cát ven biển, trên một diện tích khoảng 2 km² nằm cách trung tâm thành phố Đà Nẵng, Việt Nam khoảng 8 km về phía Đông Nam, ngay trên tuyến đường Đà Nẵng - Hội An; nay thuộcphường Ngũ Hành Sơn, thành phố Đà Nẵng."},"ban dao son tra chua linh ung":{"bai":"Sơn Trà","t":"Núi Sơn Trà, hoặc gọi là núi Khỉ, là một ngọn núi và bán đảo thuộc phường Sơn Trà, thành phố Đà Nẵng, Việt Nam, phía tây giáp vịnh Đà Nẵng, phía đông bắc và phía đông nam giáp biển Đông, phía tây nam do phù sa sông Hàn bồi đắp mà nối với đất liền hình thành bán đảo Sơn Trà, là điểm cuối cùng của dãy núi Trường Sơn Bắc."},"cau rong":{"bai":"Cầu Rồng","t":"Cầu Rồng là cây cầu thứ 6 và là cây cầu mới nhất bắc qua sông Hàn. Vì cây cầu có hình dáng giống một con rồng nên được gọi là Cầu Rồng Cầu Rồng dài 666 m và rộng 37,5 m với 6 làn xe chạy. Cầu được khởi công xây dựng vào ngày 19/7/2009 và chính thức thông xe ngày 29 tháng 3 năm 2013, kinh phí xây cầu gần 1,5 nghìn tỷ đồng (US$88m)."},"pho co hoi an":{"bai":"Phố cổ Hội An","t":"Đô thị cổ Hội An (hay Phố cổ Hội An) là một đô thị cổ nằm ở hạ lưu sông Thu Bồn, thuộc vùng đồng bằng ven biển thành phố Đà Nẵng, Việt Nam, cách trung tâm thành phố khoảng 30 km về phía Nam. Nhờ những yếu tố địa lý và khí hậu thuận lợi, Hội An từng là một thương cảng quốc tế sầm uất, nơi gặp gỡ của những thuyền buôn Nhật Bản, Trung Quốc và phương Tây trong suốt thế kỷ XVII và XVIII."},"thanh dia my son":{"bai":"Thánh địa Mỹ Sơn","t":"Thánh địa Mỹ Sơn là một quần thể di tích kiến trúc đền tháp Chăm Pa và từng là kinh đô tôn giáo và chính trị trong suốt thời gian tồn tại của vương quốc Chăm Pa, ngày nay thuộc xã Thu Bồn, thành phố Đà Nẵng. Cách thành cổ Trà Kiệu (Kinh thành Simhapura) 20 km; cách Đô thị cổ Hội An 45 km; cách Quần thể di tích Cố đô Huế 145 km và cách trung tâm thành phố Đà Nẵng 68 km."},"cho han cho con":{"bai":"Chợ Hàn","t":"Chợ Hàn là một ngôi chợ tại trung tâm thành phố Đà Nẵng. Chợ tọa lạc trên địa bàn phường Hải Châu, tiếp giáp với bốn tuyến đường Trần Phú, Bạch Đằng, Hùng Vương, Nguyễn Thái Học và cách cầu Sông Hàn không xa. Chợ Hàn được hình thành từ năm 1940. Vào năm 1989, chợ được khởi công xây mới với hai tầng khang trang trên mặt bằng diện tích 28.000 m²."},"bao tang dieu khac cham":{"bai":"Bảo tàng Điêu khắc Chăm Đà Nẵng","t":"Bảo tàng Điêu khắc Chăm Đà Nẵng, còn được gọi là Bảo tàng Chàm (dịch từ Musée Cham) là bảo tàng sưu tầm, lưu giữ và trưng bày hiện vật Chăm quy mô nhất ở Việt Nam."},"deo hai van":{"bai":"Đèo Hải Vân","t":"Đèo Hải Vân còn có tên là đèo Ải Vân (vì trên đỉnh đèo xưa kia có 1 cửa ải) hay đèo Mây (vì đỉnh đèo thường có mây che phủ), cao 500 m so với mực nước biển, dài 20 km, cắt ngang dãy dãy núi Bạch Mã (là 1 phần của dãy Trường Sơn chạy cắt ra sát biển) nằm trên quốc lộ 1 ở ranh giới thành phố Huế (ở phía Bắc) và thành phố Đà Nẵng (ở phía Nam), Việt Nam."},"chua cau":{"bai":"Chùa Cầu","t":"Chùa Cầu là một cây cầu cổ trong khu phố cổ Hội An, thành phố Đà Nẵng, Việt Nam. Cầu còn có tên gọi Cầu Nhật Bản hay Lai Viễn Kiều."},"rung dua bay mau":{"bai":"Rừng dừa Bảy Mẫu","t":"Rừng dừa Bảy Mẫu (còn gọi rừng dừa Cẩm Thanh) là vùng rừng dừa nước (Nypa fruticans) gắn với hệ sinh thái đất ngập nước ở phường Hội An Đông, thành phố Đà Nẵng. Khu vực thường được khai thác du lịch bằng hoạt động tham quan trên thuyền thúng và các tuyến đường thủy nội địa trong mạng lưới kênh rạch, lạch nước ở hạ lưu."},"lang gom thanh ha":{"bai":"Làng Thanh Hà","t":"Làng gốm Thanh Hà là một làng nghề gốm nằm ở khối phố Nam Diêu, phường Hội An Tây, thành phố Đà Nẵng. Làng gắn với không gian đô thị - thương cảng Hội An và các tuyến giao thông thủy trên sông Thu Bồn. Từ năm 2019, nghề gốm Thanh Hà được đưa vào Danh mục di sản văn hóa phi vật thể quốc gia thuộc loại hình nghề thủ công truyền thống."},"dao ly son":{"bai":"Lý Sơn","t":"Lý Sơn là một đặc khu thuộc tỉnh Quảng Ngãi, Việt Nam. Trước đây, Lý Sơn được gọi là Cù lao Ré, theo cách lý giải của dân gian là \"cù lao có nhiều cây Ré\". Hòn đảo là vết tích còn lại của một núi lửa với 5 miệng, được hình thành cách đây khoảng 25–30 triệu năm. 5 ngọn núi là nguồn giữ các mạch nước ngầm chính cung cấp nguồn nước cho toàn bộ người dân trên đảo."},"nui thien an":{"bai":"Núi Thiên Ấn","t":"Núi Thiên Ấn là một ngọn núi và cũng được xem là một thắng cảnh của tỉnh Quảng Ngãi, Việt Nam."},"khu chung tich son my":{"bai":"Khu chứng tích Sơn Mỹ","t":"Khu chứng tích Sơn Mỹ (hay Khu chứng tích Mỹ Lai), nằm trên quốc lộ 24B thuộc địa phận thôn Tư Cung, xã Tịnh Khê, tỉnh Quảng Ngãi, là nơi tưởng nhớ vụ thảm sát Sơn Mỹ (còn được biết đến là vụ thảm sát Mỹ Lai), thực hiện bởi một lực lượng của Quân đội Hoa Kỳ vào buổi sáng ngày 16 tháng 3 năm 1968, trong Chiến tranh Việt Nam."},"bien sa huynh canh dong muoi sa huynh":{"bai":"Cửa biển Sa Huỳnh","t":"Sa Huỳnh là một cửa biển ở phía đông nam tỉnh Quảng Ngãi, nơi đầm Nước Mặn thông ra Biển Đông và cũng là tên khu dân cư nằm cạnh cửa biển này. Địa danh này ngày nay còn có phạm vi rộng hơn là toàn bộ vùng đất ven biển cực nam tỉnh Quảng Ngãi, thuộc địa phận phường Sa Huỳnh và xã Khánh Cường, tỉnh Quảng Ngãi."},"thanh co chau sa":{"bai":"Thành cổ Châu Sa","t":"Thành cổ Châu Sa hay Amaravati là thủ đô của Vương quốc Amaravati, được người Chăm Pa xây dựng bằng đất vào thế kỷ thứ 9 tại xã Tịnh Khê, tỉnh Quảng Ngãi, Việt Nam. Đây là loại thành Chăm bằng đất duy nhất ngày nay vẫn còn dấu tích. Thành Châu Sa là di tích dân sự lớn nhất trong khu vực Đà Nẵng – Quảng Ngãi thuộc châu Amaravati của Champa xưa."},"bao tang tong hop quang ngai":{"bai":"Quảng Ngãi (thành phố)","t":"Quảng Ngãi trước đây là thành phố tỉnh lỵ cũ thuộc tỉnh Quảng Ngãi, vùng Duyên hải Nam Trung Bộ, Việt Nam."},"chua minh thanh":{"bai":"Chùa Minh Thành (Pleiku)","t":"Chùa Minh Thành là ngôi chùa nằm cách trung tâm đô thị Pleiku khoảng 2Km tọa lạc ở số 348 đường Nguyễn Viết Xuân, phường Hội Phú, tỉnh Gia Lai. Chùa Minh Thành được xem là điểm tham quan hấp dẫn của khu vực Pleiku - Gia Lai. Chùa Minh Thành là sự giao thoa giữa văn hóa kiến trúc thời Lý - Trần và phong cách chùa Nhật Bản."},"thac phu cuong":{"bai":"Thác Phú Cường","t":"Thác Phú Cường là thác trên sông Ia Pết ở vùng đất xã Chư Sê, tỉnh Gia Lai, Việt Nam. Thác Phú Cường nằm cách quốc lộ 25 từ ngã ba Phú Cường về phía đông cỡ 1,3 km theo đường thẳng, và đi đường bộ thì cỡ 2 km. Thác cách thị trấn Chư Sê cỡ 18 km. Thác có độ cao chừng 45 m, với không gian thoáng đãng, không khí trong lành."},"thap doi":{"bai":"Tháp Đôi","t":"Tháp Đôi hay còn có tên là Tháp Hưng Thạnh còn trong tiếng J'rai gọi là SRI BANOI là khu tháp của Chăm Pa gồm có hai tháp là tháp phía bắc và tháp phía nam cạnh nhau hiện nằm ở phường Quy Nhơn, tỉnh Gia Lai, Việt Nam."},"ho lak":{"bai":"Hồ Lắk","t":"Hồ Lắk là một hồ nước ngọt tự nhiên lớn nhất tỉnh Đăk Lăk và hồ tự nhiên lớn thứ hai Việt Nam sau Hồ Ba Bể. Xung quanh hồ có những dãy núi lớn được bao phủ bởi các cánh rừng nguyên sinh. Buôn Jun, một buôn làng nổi tiếng của người M'Nông, nằm cạnh hồ này. Xung quanh hồ còn có những kiến trúc lịch sử như biệt điện của hoàng đế Bảo Đại, nhà dài của người M'Nông."},"vuon quoc gia yok don":{"bai":"Vườn quốc gia Yok Đôn","t":"Vườn quốc gia Yok Đôn là một trong những khu rừng đặc dụng lớn nhất Việt Nam, thuộc 2 tỉnh Lâm Đồng và Đắk Lắk."},"chua sac tu khai doan":{"bai":"Chùa Khải Đoan","t":"Chùa Khải Đoan ) là ngôi chùa lớn nhất ở phường Buôn Ma Thuột, tỉnh Đắk Lắk, Việt Nam. Đây cũng là ngôi chùa lần đầu tiên được xây dựng ở Cao Nguyên. Tên gọi Khải Đoan là ghép từ tên vua Khải Định và vợ ông là Đoan Huy hoàng hậu."},"buon ako dhong":{"bai":"Buôn Akõ Dhông","t":"Buôn Akŏ Dhông tiếng Ê Đê, “Akŏ” có nghĩa là đầu nguồn, “Dhông” là \"triền dốc\". Akŏ Dhông là \"đầu dốc\" đặt tên như vậy vì buôn này nằm sát dốc của đầu nguồn suối Ea Nuôl."},"lang ca phe trung nguyen":{"bai":"Làng cà phê Trung Nguyên","t":"Làng cà phê Trung Nguyên hay còn được gọi là Làng Cà phê là một cụm công trình kiến trúc có diện tích khoảng 20.000m². Làng Cà phê Trung Nguyên nằm ở phường Buôn Ma Thuột, tỉnh Đắk Lắk, tọa lạc tại ngã ba Lý Thái Tổ - Nguyễn Hữu Thọ. Đây là một địa điểm du lịch nổi tiếng ở Tây Nguyên với không gian kiến trúc độc đáo đậm đà bản sắc dân tộc và không gian cà phê đặc sắc."},"thap nhan":{"bai":"Tháp Nhạn","t":"Tháp Nhạn, trong tiếng Ê-Đê và Jarai gọi là Yang Kơ Hmeng, là một tháp Chăm nằm trên núi Nhạn thuộc phường Tuy Hòa, tỉnh Đắk Lắk. Tháp được người Chăm sinh sống ở lưu vực châu thổ sông Ba xây dựng nên vào khoảng thế kỉ 12. Tháp có hình tứ giác với 4 tầng, càng lên cao càng thu nhỏ lại so với tầng dưới, nhưng vẫn theo phong cách tầng dưới. Tháp cao khoảng 23,5m. Mỗi cạnh chân tháp dài 10m."},"ganh da dia":{"bai":"Gành Đá Đĩa","t":"Gành Đá Đĩa hay Ghềnh Đá Đĩa là một danh thắng thiên nhiên tại xã Tuy An Đông, tỉnh Đắk Lắk, Việt Nam. Địa điểm này là một đoạn bờ biển có các cột đá bazan hình lăng trụ, trông giống như những chiếc đĩa xếp chồng lên nhau."},"thap tram huong quang truong 2 4":{"bai":"Tháp Trầm Hương","t":"Tháp Trầm Hương là một công trình kiến trúc biểu tượng của Nha Trang, Khánh Hòa. Tòa tháp nằm tại quảng trường Hai tháng Tư dọc theo đường Trần Phú và gần Trung tâm Văn hóa Khánh Hòa. Tháp Trầm Hương là nơi trưng bày hình ảnh và sản vật địa phương và quảng bá du lịch cho Nha Trang."},"cho dam":{"bai":"Chợ Đầm","t":"Chợ Đầm là chợ trung tâm của phường Nha Trang, tỉnh Khánh Hòa, Việt Nam, là một công trình kiến trúc đẹp, độc đáo. Đây là chợ lớn nhất và cũng là biểu tượng thương mại của thành phố biển này. Đây là trung tâm thương mại mua sắm và cũng là điểm tham quan du lịch."},"nha tho nui":{"bai":"Nhà thờ Núi Nha Trang","t":"Nhà thờ Núi (tên chính thức là: Nhà thờ chính tòa Kitô Vua) là một nhà thờ Công giáo ở số 1 đường Thái Nguyên, phường Nha Trang, tỉnh Khánh Hòa."},"hon chong":{"bai":"Hòn Chồng","t":"Hòn Chồng là một thắng cảnh tự nhiên ở phường Bắc Nha Trang, tỉnh Khánh Hòa. Khu vực này là một bãi đá được xếp chồng lên nhau một cách tự nhiên, ngoài ra còn có Hòn vợ ở gần đó và Hội quán vịnh Nha Trang có dạng nhà rường Huế được xây ở phía trên."},"vien hai duong hoc":{"bai":"Viện Hải dương học","t":"Viện Hải dương học là một viện nghiên cứu đời sống động - thực vật hải dương tại thành phố Nha Trang, tỉnh Khánh Hòa. Viện Hải dương học là một trong những cơ sở nghiên cứu khoa học được ra đời sớm nhất ở Việt Nam và được coi là cơ sở lưu trữ hiện vật và nghiên cứu về biển lớn nhất Đông Nam Á."},"vinh vinh hy":{"bai":"Vịnh Vĩnh Hy","t":"Vịnh Vĩnh Hy, tên khác là Vũng Găng, là một vịnh nhỏ nằm ở xã Vĩnh Hải, tỉnh Khánh Hòa, Việt Nam."},"thap po klong garai":{"bai":"Tháp Po Klong Garai","t":"Tháp Po Klong Garai là tên gọi chung cho một cụm tháp Chăm hùng vĩ và đẹp nhất còn lại ở Việt Nam, phụng thờ vua Po Klong Garai. Tháp Pô Klong Garai là một tổng thể gồm ba tháp: tháp chính (cao 20,5m), tháp lửa (cao 9,31m), tháp cổng (cao 8,56m). Công trình này có trình độ kiến trúc, nghệ thuật, điêu khắc đạt đến đỉnh cao."},"ho xuan huong":{"bai":"Hồ Xuân Hương","t":"Hồ Xuân Hương là một nữ thi sĩ người Việt Nam sống ở giai đoạn cuối thế kỷ XVIII và đầu thế kỷ XIX, mà hiện tại vẫn khiến nhiều học giả tranh cãi. Bà được nhà thơ hiện đại Xuân Diệu mệnh danh là Bà chúa thơ Nôm. Năm 2021, bà cùng Nguyễn Đình Chiểu là hai nhà thơ của Việt Nam được UNESCO vinh danh là \"danh nhân văn hóa thế giới\" cùng với kỷ niệm năm sinh/năm mất."},"quang truong lam vien":{"bai":"Quảng trường Lâm Viên","t":"Quảng trường Lâm Viên là quảng trường nằm ở đường Trần Quốc Toản, đối diện hồ Xuân Hương, phường Xuân Hương - Đà Lạt, tỉnh Lâm Đồng. Quảng trường có tên gọi khác là Trung tâm Đà Lạt, được đặt tên Lâm Viên dựa trên vị trí địa lý của thành phố, nằm trên cao nguyên Lâm Viên (cao nguyên Lang Biang), cũng như vùng đất từng gọi là tỉnh Lâm Viên."},"ga da lat":{"bai":"Ga Đà Lạt","t":"Ga Đà Lạt là nhà ga tàu hỏa của phường Xuân Hương - Đà Lạt. Nhà ga được người Pháp xây dựng từ năm 1932 đến 1938 thì hoàn thành, là nhà ga đầu mối trên tuyến đường sắt Tháp Chàm – Đà Lạt dài 84 km. Nhà ga có phong cách kiến trúc độc đáo, có ba mái hình chóp, là cách điệu ba đỉnh núi Langbiang hoặc nhà rông Tây Nguyên."},"thung lung tinh yeu":{"bai":"Thung lũng Tình Yêu","t":"Thung Lũng Tình Yêu là một trong những thắng cảnh thơ mộng nhất tại Đà Lạt, cách trung tâm thành phố khoảng 5 km về phía bắc. Địa chỉ: số 3–7 đường Mai Anh Đào, phường Lâm Viên – Đà Lạt, tỉnh Lâm Đồng. Đó là nơi đập Đa Thiện quy tụ những dòng suối nhỏ chảy từ đồi núi cao, thành hồ Đa Thiện trong vắt uốn quanh thung lũng rợp bóng thông xanh."},"nui langbiang":{"bai":"Núi Langbiang","t":"Núi Langbiang là một cụm núi cao tại tỉnh Lâm Đồng, nằm cách phường Xuân Hương – Đà Lạt 12 km thuộc địa phận phường Lang Biang – Đà Lạt. Hai núi cao nhất tại đây là núi Bà cao 2.167 m và núi Ông cao 2.124 m so với mặt nước biển. Ngoài ra trong khu du lịch còn có ngọn đồi Ra-đa cao 1.929 m, ngọn đồi này cũng là một địa điểm quen thuộc đối với du khách."},"lang cu lan":{"bai":"Làng Cù Lần","t":"Làng Cù Lần là một điểm tham quan của du lịch Đà Lạt. Làng Cù Lần là một ngôi làng nhỏ rộng chừng 30 héc-ta nằm lọt thỏm giữa hàng ngàn héc-ta rừng nguyên sinh hoang dã dưới chân đỉnh núi LangBiAng trải rộng. Làng Cù Lần cách Hồ Xuân Hương 21 km, cách khu du lịch Suối Vàng 9 km vào hướng Suối Vàng - Suối Bạc. Dòng suối Bạc là dòng suối nằm trong Làng Cù Lần."},"ho tuyen lam":{"bai":"Hồ Tuyền Lâm","t":"Hồ Tuyền Lâm là một hồ nước thuộc phường Xuân Hương – Đà Lạt, tỉnh Lâm Đồng. Đây là hồ nước ngọt rộng nhất khu vực Đà Lạt, với diện tích khoảng 320 ha, nằm cách trung tâm tỉnh Lâm Đồng 7 km và cách thác Ðatanla 2 km. Hồ nằm gần núi Phụng Hoàng, đây được xem là khu phức hợp tập trung nhiều cảnh quan đẹp và dịch vụ du lịch phong phú."},"thac datanla":{"bai":"Thác Datanla","t":"Đatanla hay Datanla là thác ở phường Xuân Hương – Đà Lạt, tỉnh Lâm Đồng, Việt Nam. Thác nằm trong khu du lịch Đatanla, cách thác Prenn 8 km và trung tâm phường 10 km và là điểm tham quan, phiêu lưu mạo hiểm. Tên gọi \"Đatanla\" hay \"Đatania\" theo tiếng K'Ho ghép lại từ \"Đạh-Tam-N'ha\" có nghĩa là \"dưới lá có nước\", và có liên quan đến cuộc xung đột Chăm - Lạch - Chil hồi thế kỷ XV - XVII."},"thac prenn":{"bai":"Thác Prenn","t":"Thác Prenn là một thác nước ở phường Xuân Hương – Đà Lạt thuộc tỉnh Lâm Đồng, Việt Nam. Thác Prenn nằm cạnh quốc lộ 20, ở cửa ngõ vào TP.Đà Lạt là một trong những KDL sinh thái về rừng, suối. Thác ở chân đèo Prenn cách trung tâm Đà Lạt khoảng 10 km. Thác nằm trong khu rừng nguyên sinh còn sót lại."},"nha tho domaine de marie":{"bai":"Nhà thờ Domaine de Marie","t":"Nhà thờ Domaine de Marie còn được gọi là Nhà thờ Vinh Sơn (vì là nguyện đường của các sœurs Nữ Tử Bác Ái Vinh Sơn), Nhà thờ Mai Anh (vì trước đây khu vực này có rất nhiều hoa mai anh đào)."},"biet thu hang nga":{"bai":"Biệt thự Hằng Nga","t":"Biệt thự Hằng Nga hay Ngôi nhà quái dị (được biết đến với tên tiếng Anh: Crazy House) là một nhà nghỉ tại phường Xuân Hương – Đà Lạt, tỉnh Lâm Đồng, nằm ở số 3 Huỳnh Thúc Kháng trong khuôn viên rộng gần 4.000 m². Ngôi nhà này nổi tiếng vì có phong cách kiến trúc đặc biệt."},"ho suoi vang":{"bai":"Hồ Đankia – Suối Vàng","t":"Hồ Đankia – Suối Vàng là cụm hồ ở vùng đất thôn Đan Kia, phường Lang Biang – Đà Lạt, tỉnh Lâm Đồng. Hồ nằm cách trung tâm tỉnh khoảng 20 km về phía Bắc."},"van mieu tran bien":{"bai":"Văn miếu Trấn Biên","t":"Văn miếu Trấn Biên là \"Văn miếu\" đầu tiên được xây dựng (xây năm 1715) tại xứ Đàng Trong, để tôn vinh Khổng Tử, các danh nhân văn hóa nước Việt và là nơi đào tạo nhân tài phục vụ cho chế độ. Năm 1861, nơi thờ phụng trên đã bị thực dân Pháp phá bỏ. Mãi đến năm 1998, Văn miếu Trấn Biên mới được khởi công khôi phục lại nơi vị trí cũ, và hoàn thành vào năm 2002."},"khu du lich buu long":{"bai":"Khu du lịch Bửu Long","t":"Khu du lịch Bửu Long nằm ở phường Trấn Biên, thành phố Đồng Nai, cách thành phố Hồ Chí Minh chỉ 30 km về hướng Đông. Diện tích khoảng 84 ha, cao trung bình 100m so với mặt nước biển."},"ho tri an":{"bai":"Hồ Trị An","t":"Hồ Trị An là một hồ nước nhân tạo nằm trên sông Đồng Nai, thuộc phường Trị An và các xã Bàu Hàm, Thống Nhất, La Ngà, Định Quán, Thanh Sơn và Phú Lý, thành phố Đồng Nai, Việt Nam. Hồ là nơi trữ nước để cung cấp cho Nhà máy thủy điện Trị An. Hồ Trị An được khởi công vào năm 1984 và hoàn thành đầu năm 1987."},"thac giang dien":{"bai":"Thác Giang Điền","t":"Giang Điền là một thác nước nằm trên sông Buông ở khu phố Hòa Bình, phường Trảng Bom, thành phố Đồng Nai, Việt Nam. Thác Giang Điền là tập hợp gồm ba dòng thác: thác Chàng, thác Nàng và thác chính Giang Điền. Thác nằm cách phường Biên Hòa chừng 15 km, cách Thành phố Hồ Chí Minh khoảng 45 km. Theo các già làng trong vùng kể lại rằng vùng đất này ngày xưa là nơi người Mạ sinh sống."},"vuon quoc gia nam cat tien":{"bai":"Vườn quốc gia Cát Tiên","t":"Vườn quốc gia Cát Tiên là một khu bảo tồn thiên nhiên, vườn quốc gia tại Việt Nam. Nó nằm trên địa bàn thành phố Đồng Nai, cách Thành phố Hồ Chí Minh 150 km về phía bắc. Điểm đặc trưng của vườn quốc gia này là rừng đất thấp ẩm ướt nhiệt đới."},"nui chua chan":{"bai":"Núi Chứa Chan","t":"Núi Chứa Chan (còn gọi núi Gia Ray hay núi Gia Lào) thuộc phường Xuân Lộc, thành phố Đồng Nai, Việt Nam. Ngọn núi này được Bộ Văn hóa, Thể thao và Du lịch Việt Nam xếp hạng di tích danh lam thắng cảnh cấp quốc gia theo Quyết định số 1204/QĐ-BVHTTDL ngày 29 tháng 3 năm 2012. Có độ cao khoảng 837 m so với mực nước biển, là ngọn núi cao thứ hai vùng Nam Bộ chỉ sau núi Bà Đen (Tây Ninh)."},"nui ba ra ho thac mo":{"bai":"Núi Bà Rá","t":"Núi Bà Rá là một ngọn núi nằm trên địa phận phường Phước Long, thành phố Đồng Nai và miền Đông Nam Bộ, Việt Nam, cách Thành phố Hồ Chí Minh 160 km về phía tây bắc. Đây là ngọn núi cao thứ 3 ở Nam Bộ."},"ho thac mo":{"bai":"Thủy điện Thác Mơ","t":"Nhà máy thủy điện Thác Mơ là một nhà máy thủy điện trên sông Bé thuộc địa bàn xã Phú Nghĩa, thành phố Đồng Nai, Việt Nam."},"vuon quoc gia bu gia map":{"bai":"Vườn quốc gia Bù Gia Mập","t":"Vườn quốc gia Bù Gia Mập là nơi bảo tồn các nguồn sinh quyển ở miền Đông Nam Bộ, Việt Nam."},"nui ba den":{"bai":"Núi Bà Đen","t":"Núi Bà Già là ngọn núi lửa đã tắt nằm phần lớn ở phường Bình Minh, tỉnh Tây Ninh, Việt Nam. Với độ cao 986 m, đây là ngọn núi cao nhất miền Nam Việt Nam hiện nay, được mệnh danh \"Đệ nhất thiên sơn\". Theo Gia Định thành thông chí, tên gốc của núi Bà Đen là Bà Dinh. Những bậc kỳ lão địa phương cho rằng tên gốc là núi Một."},"thung lung ma thien lanh":{"bai":"Thung lũng Ma Thiên Lãnh","t":"Thung lũng Ma Thiên Lãnh là một thung lũng tại Tây Ninh nằm trong quần thể núi Bà Đen, là nơi tiếp giáp giữa ba ngọn núi là núi Heo (núi Đất), núi Phụng và núi Bà Đen thuộc địa phận phường Bình Minh. Nhiều tờ báo của Việt Nam đã ví von nơi này như \"Đà Lạt của Đông Nam Bộ\" vì không khí trong lành, mát mẻ. Ma Thiên Lãnh nằm cách thành phố Tây Ninh khoảng 10 km về hướng Đông – Bắc."},"chua go ken":{"bai":"Chùa Gò Kén","t":"Chùa Gò Kén hay Từ Lâm Tự, chùa Thiền Lâm là một ngôi chùa Phật giáo nằm tại ấp Long Trung, phường Hòa Thành, tỉnh Tây Ninh. Đây là một trong những kiến trúc Phật giáo có mặt sớm nhất ở Tây Ninh khi có tuổi đời hơn 100 năm tuổi. Đây cũng là nơi mà Cao Huỳnh Cư, Cao Hoài Sang và Phạm Công Tắc mượn làm nơi khai sinh ra đạo Cao Đài. Trụ trì chùa hiện nay là Thích Thiện Nghĩa."},"ho dau tieng":{"bai":"Hồ Dầu Tiếng","t":"Hồ Dầu Tiếng là một hồ nước nhân tạo nằm trên địa bàn ba tỉnh thành Tây Ninh, Thành phố Hồ Chí Minh và thành phố Đồng Nai thuộc vùng Đông Nam Bộ, Việt Nam. Hồ được hình thành do việc chặn dòng thượng nguồn sông Sài Gòn, đây hiện là hồ thủy lợi lớn nhất Việt Nam và Đông Nam Á. Hồ được khởi công vào năm 1981 sau khi công tác khảo sát bắt đầu được thực hiện từ năm 1976."},"vuon quoc gia lo go xa mat":{"bai":"Vườn quốc gia Lò Gò – Xa Mát","t":"Vườn quốc gia Lò Gò – Xa Mát (còn được gọi là Khu bảo tồn quốc gia Lò Gò – Xa Mát) là một vườn quốc gia của Việt Nam, được thành lập theo Quyết định số 91/2002/QĐ-TTg của Thủ tướng Chính phủ nước Cộng hòa xã hội chủ nghĩa Việt Nam trên cơ sở nâng cấp Khu Bảo tồn thiên nhiên Lò Gò - Xa Mát. Đến năm 2020, vườn quốc gia được mở rộng trên cơ sở sáp nhập thêm Khu rừng Văn hóa - Lịch sử Chàng Riệc."},"lang noi tan lap":{"bai":"Rừng tràm Tân Lập","t":"Rừng tràm Tân Lập là khu vực rừng tràm ngập nước nằm tại xã Mộc Hóa, tỉnh Tây Ninh. Khu vực đã được sử dụng khai thác du lịch với tên gọi Khu du lịch sinh thái làng nổi Tân Lập hay ngắn gọn là Làng nổi Tân Lập."},"dinh doc lap":{"bai":"Dinh Độc Lập","t":"Dinh Độc Lập là một tòa dinh thự tại Thành phố Hồ Chí Minh, từng là nơi ở và làm việc của Tổng thống Việt Nam Cộng hòa trước Sự kiện 30 tháng 4 năm 1975. Hiện nay, Dinh Độc Lập đã được Chính phủ Việt Nam xếp hạng là di tích quốc gia đặc biệt. Cơ quan quản lý di tích văn hóa Dinh Độc Lập có tên là Hội trường Thống Nhất thuộc Văn phòng Chính phủ."},"cho ben thanh":{"bai":"Chợ Bến Thành","t":"Chợ Bến Thành là một ngôi chợ nằm tại phường Bến Thành, Thành phố Hồ Chí Minh. Chợ được khởi công xây dựng từ năm 1912, hình ảnh đồng hồ ở cửa nam của ngôi chợ này được xem là biểu tượng không chính thức của Thành phố Hồ Chí Minh. Chợ nằm giữa các đường Phan Bội Châu - Phan Chu Trinh - Lê Thánh Tôn - Công trường Quách Thị Trang tại phường Bến Thành với diện tích 13.056 m²."},"pho di bo nguyen hue":{"bai":"Đường Nguyễn Huệ, Thành phố Hồ Chí Minh","t":"Đường Nguyễn Huệ là một tuyến đường tại phường Sài Gòn (Quận 1 cũ), trung tâm Thành phố Hồ Chí Minh, chạy từ Trụ sở Ủy ban nhân dân Thành phố đến Bến Bạch Đằng, bờ sông Sài Gòn. Hiện nay chính giữa con đường này là một quảng trường đi bộ rộng 27 m được đưa vào sử dụng từ năm 2015, là quảng trường đi bộ đầu tiên của Việt Nam."},"nha tho duc ba sai gon":{"bai":"Nhà thờ chính tòa Đức Bà Sài Gòn","t":"Nhà thờ Chánh tòa Đức Bà Sài Gòn (hay Vương cung thánh đường chánh tòa Đức Mẹ Vô nhiễm Nguyên tội, tiếng Anh: Immaculate Conception Cathedral Basilica, tiếng Pháp: Cathédrale Notre-Dame de Saïgon, tiếng Latinh: Basilica Immaculatae Conceptionis), thường được gọi tắt là Nhà thờ Đức Bà, là nhà thờ chính tòa của Tổng giáo phận Sài Gòn."},"buu dien trung tam sai gon":{"bai":"Bưu điện Sài Gòn","t":"Bưu điện Trung tâm Sài Gòn, còn gọi là Tòa nhà Bưu điện Thành phố Hồ Chí Minh, là một trong những công trình kiến trúc tiêu biểu tại Thành phố Hồ Chí Minh, tọa lạc tại số 2, Công trường Công xã Paris, phường Sài Gòn. Đây là tòa nhà được người Pháp xây dựng trong khoảng năm 1886–1891 với phong cách chiết trung theo đồ án thiết kế của kiến trúc sư Marie-Alfred Foulhoux."},"bao tang chung tich chien tranh":{"bai":"Bảo tàng Chứng tích chiến tranh","t":"Bảo tàng Chứng tích Chiến tranh (War Remnants Museum) là một bảo tàng vì hòa bình ở số 28 đường Võ Văn Tần, phường Xuân Hòa, Thành phố Hồ Chí Minh. Bảo tàng Chứng tích Chiến tranh trực thuộc Sở Văn hóa và Thể thao Thành phố Hồ Chí Minh, là thành viên của hệ thống Bảo tàng vì hòa bình thế giới và Hội đồng các bảo tàng thế giới (ICOM)."},"bao tang lich su tp hcm":{"bai":"Bảo tàng Lịch sử Thành phố Hồ Chí Minh","t":"Bảo tàng Lịch sử Thành phố Hồ Chí Minh tọa lạc tại số 2 đường Nguyễn Bỉnh Khiêm, phường Sài Gòn, trong khuôn viên Thảo Cầm Viên Sài Gòn. Đây là nơi bảo tồn và trưng bày hàng chục ngàn hiện vật quý được sưu tầm trong và ngoài nước Việt Nam."},"ben bach dang buyt duong song":{"bai":"Bến Bạch Đằng","t":"Bến Bạch Đằng là tên của khu vực công viên và bến sông bên bờ sông Sài Gòn tại Sài Gòn, trung tâm Thành phố Hồ Chí Minh, Việt Nam. Đây là nơi người dân thành phố và du khách tới vui chơi và là địa điểm ngắm pháo hoa mỗi dịp lễ, Tết. Bến Bạch Đằng ở địa chỉ số 2 đường Tôn Đức Thắng, nằm bên bờ tây sông Sài Gòn, gồm bến cảng và công viên dài 1,3 km, rộng 23.400 m²."},"dia dao cu chi":{"bai":"Địa đạo Củ Chi","t":"Địa đạo Củ Chi là một hệ thống phòng thủ trong lòng đất ở xã An Nhơn Tây, cách trung tâm Thành phố Hồ Chí Minh 69 km về hướng Tây-Bắc. Hệ thống này được quân kháng chiến Việt Minh và Mặt trận Dân tộc Giải phóng miền Nam Việt Nam đào trong thời kỳ Chiến tranh Đông Dương và Chiến tranh Việt Nam."},"cho lon chua ba thien hau":{"bai":"Chợ Lớn","t":"Chợ Lớn là một khu vực đông Hoa kiều sinh sống nằm ven kênh Tàu Hủ trải dài trên địa bàn Quận 5 và Quận 6 cũ, về phía nam tới Quận 8 cũ, về phía bắc tới Quận 10 và Quận 11 cũ ở Thành phố Hồ Chí Minh, Việt Nam. Khu phố Chợ Lớn đã có Hoa kiều sinh sống từ lâu và được coi là phố người Hoa lớn nhất thế giới tính theo diện tích."},"thao cam vien sai gon":{"bai":"Thảo Cầm Viên Sài Gòn","t":"Thảo Cầm Viên Sài Gòn, hay còn được gọi ở địa phương là Sở Thú, là công viên bảo tồn động vật - thực vật rộng hơn 20 ha ở Thành phố Hồ Chí Minh, Việt Nam. Khuôn viên này hiện tọa lạc gần hạ lưu kênh Nhiêu Lộc – Thị Nghè với hai cổng nằm ở số 2 đường Nguyễn Bỉnh Khiêm và số 1 đường Nguyễn Thị Minh Khai, phường Sài Gòn, Thành phố Hồ Chí Minh."},"khu du lich dai nam":{"bai":"Lạc Cảnh Đại Nam Văn Hiến","t":"Lạc cảnh Đại Nam Văn Hiến (hay còn gọi là Đại Nam Du lịch thần tiên) là một khu du lịch tọa lạc tại phường Phú An, thành phố Hồ Chí Minh, Việt Nam. Đây là công trình du lịch quy mô lớn được xây dựng từ năm 1999 với tổng kinh phí khoảng 6.000 tỷ đồng và sau đó bắt đầu mở cửa đón du khách từ ngày 11 tháng 9 năm 2008 đến nay."},"tuong chua kito vua":{"bai":"Tượng Chúa Kitô Vua (Vũng Tàu)","t":"Tượng Chúa Kitô Vua (hoặc Tượng Đức Chúa dang tay, Tượng Chúa Kitô trên đỉnh Núi Tao Phùng) là một bức tượng Chúa Giêsu được đặt trên đỉnh Núi Nhỏ của phường Vũng Tàu, Thành phố Hồ Chí Minh (được xây từ năm 1974). Tượng đã được xác lập là \"Tượng Chúa Giêsu lớn nhất khu vực châu Á\" vào năm 2012."},"van thanh mieu":{"bai":"Văn Thánh Miếu Vĩnh Long","t":"Văn Thánh Miếu Vĩnh Long cùng với Văn miếu Trấn Biên (Đồng Nai), Văn Thánh miếu Gia Định, là ba Văn Thánh miếu của vùng đất Nam Bộ có từ thế kỷ 19 được xây dựng nhằm đề cao Nho giáo."},"cau my thuan":{"bai":"Cầu Mỹ Thuận","t":"Cầu Mỹ Thuận là cây cầu dây văng bắc qua sông Tiền, nối liền hai tỉnh Đồng Tháp với Vĩnh Long. Cầu nằm cách TP.HCM 125 km về hướng tây nam, nằm tại Km 2028+134 Quốc lộ 1, là trục giao thông chính của vùng Đồng bằng sông Cửu Long. Cầu Mỹ Thuận là cầu dây văng và cầu bắc qua sông Mê Kông đầu tiên ở Việt Nam, được mệnh danh là \"cây cầu thế kỉ\" do được khánh thành vào năm 2000."},"cu lao an binh":{"bai":"Cù lao An Bình","t":"Cù lao An Bình là cù lao nằm giữa sông Tiền và sông Cổ Chiên thuộc tỉnh Vĩnh Long, Việt Nam."},"cho noi tra on":{"bai":"Chợ nổi Trà Ôn","t":"Chợ nổi Trà Ôn là một chợ nổi ở xã Trà Ôn, tỉnh Vĩnh Long. Đây là chợ nổi cuối cùng trên sông Hậu trước khi đổ ra biển. Chợ nằm ngay giữa ngã ba sông Hậu và sông Mang Thít."},"lang gach gom mang thit":{"bai":"Mang Thít","t":"Mang Thít là một huyện cũ thuộc tỉnh Vĩnh Long. Nay là xã Cái Nhum, Nhơn Phú, Bình Phước, Tân Long Hội thuộc tỉnh Vĩnh Long, Việt Nam."},"cu lao may":{"bai":"Cù lao Mây","t":"Cù lao Mây hay còn gọi là Cù lao Lục Sĩ Thành nằm giữa dòng sông Hậu thuộc xã Lục Sĩ Thành, tỉnh Vĩnh Long, Việt Nam."},"con phung":{"bai":"Cồn Phụng","t":"Cồn Phụng nằm trên một cù lao nổi giữa sông Mỹ Tho (một đoạn của sông Tiền) thuộc xã Phú Túc, tỉnh Vĩnh Long, Việt Nam."},"nha co huynh thuy le":{"bai":"Nhà cổ Huỳnh Thủy Lê","t":"Nhà cổ Huỳnh Thủy Lê là một ngôi nhà cổ tọa lạc tại số 255A, đường Nguyễn Huệ, khu phố Kiến An, phường Sa Đéc, tỉnh Đồng Tháp, Việt Nam."},"khu di tich lang cu pho bang nguyen sinh sac":{"bai":"Nguyễn Sinh Sắc","t":"Nguyễn Sinh Sắc ; sách báo thường gọi bằng tên cụ Phó bảng; cụ Sắc, 1862 – 27 tháng 11, 1929) là cha ruột của Chủ tịch nước Việt Nam đầu tiên – Hồ Chí Minh."},"khu du lich sinh thai gao giong":{"bai":"Khu du lịch sinh thái Gáo Giồng","t":"Khu du lịch sinh thái Gáo Giồng nằm tại ấp 6, xã Gáo Giồng, huyện Cao Lãnh, tỉnh Đồng Tháp; cách trung tâm thành phố Cao Lãnh khoảng 15 km. Khu du lịch sinh thái này hình thành trên cơ sở rừng tràm Gáo Giồng. Rừng tràm Gáo Giồng được thành lập năm 1985 với diện tích 1.657 ha."},"vuon quoc gia tram chim":{"bai":"Vườn quốc gia Tràm Chim","t":"Vườn quốc gia Tràm Chim thuộc tỉnh Đồng Tháp là một khu đất ngập nước, được xếp trong hệ thống rừng đặc dụng của Việt Nam. Nơi đây có nhiều loài chim quý, đặc biệt là sếu đầu đỏ, một loài chim cực kỳ quý hiếm, có tên trong sách đỏ."},"khu du lich sinh thai dong sen thap muoi":{"bai":"Đồng Tháp","t":"Đồng Tháp là một tỉnh thuộc vùng Đồng bằng sông Cửu Long của Việt Nam. Đây là một trong 34 tỉnh, thành trên cả nước. Tỉnh được thành lập trên cơ sở hợp nhất tỉnh Kiến Phong, Sa Đéc vào ngày 24 tháng 2 năm 1976 và sau đó hợp nhất với tỉnh Tiền Giang vào tháng 6 năm 2025."},"khu di tich go thap":{"bai":"Gò Tháp","t":"Khu di tích Gò Tháp là một di tích quốc gia đặc biệt, nằm trên địa bàn hai xã Tháp Mười và Đốc Binh Kiều, tỉnh Đồng Tháp, cách Cao Lãnh về hướng Đông Bắc 43 km (theo đường bộ và đường thủy)."},"vuon quyt hong lai vung":{"bai":"Quýt hồng","t":"Quýt hồng là một giống quýt đặc sản được trồng chủ yếu tại tỉnh Đồng Tháp, Việt Nam. Quýt hồng là một trong những đặc sản trái cây nổi tiếng ở khu vực đồng bằng sông Cửu Long. Với những đặc điểm riêng biệt về hương vị, màu sắc cũng như các đặc tính của quả, khiến cho quýt hồng ngày nay trở nên nổi tiếng khắp toàn quốc và xuất khẩu sang một số quốc gia."},"cho chieu dinh yen":{"bai":"Làng chiếu Định Yên","t":"Làng chiếu Định Yên là một làng nghề truyền thống chuyên sản xuất các loại chiếu bằng sợi lác tọa lạc tại xã Lai Vung, tỉnh Đồng Tháp, Việt Nam. Nghề dệt chiếu tại làng chiếu Định Yên được Bộ Văn hóa, Thể thao và Du lịch Việt Nam công nhận là Di sản văn hóa phi vật thể quốc gia vào năm 2013."},"cho noi cai be":{"bai":"Chợ nổi Cái Bè","t":"Chợ nổi Cái Bè là một chợ nổi thuộc xã Cái Bè, tỉnh Đồng Tháp. Địa điểm là nơi trao đổi mua bán hàng hóa, đặc biệt là các loại trái cây và là điểm tham quan du lịch của tỉnh Đồng Tháp. Chợ nổi này là một trong các chợ nổi ở miền Tây Nam Bộ cũng như là nơi buôn bán mang sắc thái rất riêng của vùng Đồng bằng sông Cửu Long, sự kết hợp giữa văn hóa sông nước và miệt vườn cây ăn trái."},"chua vinh trang":{"bai":"Chùa Vĩnh Tràng","t":"Chùa Vĩnh Tràng tọa lạc trên đường Nguyễn Trung Trực, khu phố Mỹ An, phường Mỹ Phong, tỉnh Đồng Tháp, Việt Nam."},"mieu ba chua xu nui sam":{"bai":"Miếu Bà Chúa Xứ Núi Sam","t":"Miếu Bà Chúa xứ Núi Sam nằm ở nơi chân núi Sam, thuộc phường Vĩnh Tế, tỉnh An Giang."},"lang thoai ngoc hau":{"bai":"Lăng Thoại Ngọc Hầu","t":"Lăng Thoại Ngọc Hầu còn gọi là Sơn Lăng, thuộc phường Vĩnh Tế, tỉnh An Giang. Đây là một danh thắng, một công trình kiến trúc cổ tiêu biểu dưới thời phong kiến, và là một di tích lịch sử cấp quốc gia Việt Nam (xếp hạng năm 1997)."},"chua tay an":{"bai":"Chùa Tây An","t":"Chùa Tây An còn được gọi là Chùa Tây An Núi Sam, là một ngôi chùa Phật giáo tọa lạc tại ngã ba, dưới chân núi núi Sam (nay thuộc phường Vĩnh Tế, tỉnh An Giang)."},"rung tram tra su":{"bai":"Rừng tràm Trà Sư","t":"Rừng tràm Trà Sư là một khu rừng và khu du lịch sinh thái nằm trên địa bàn ấp Văn Râu, xã An Cư, tỉnh An Giang. Đây là rừng ngập nước tiêu biểu cho vùng Tây sông Hậu, là nơi sinh sống của nhiều loài động vật và thực vật thuộc hệ thống rừng đặc dụng Việt Nam."},"ta pa":{"bai":"Núi Tà Pạ","t":"Núi Tà Pạ còn gọi là đồi Tà Pạ thuộc xã Tri Tôn, Tỉnh An Giang. Từ chợ Tri Tôn đi hết đường Nguyễn Trãi một đoạn ngắn (theo hướng về Khu du lịch đồi Tức Dụp), sẽ bắt gặp cây lâm vồ to lớn. Đối diện với gốc cây cổ thụ này là cổng chùa, người dân hay gọi là chùa Núi, nơi bắt đầu con đường chính dẫn lên đồi Tà Pạ."},"cho noi long xuyen":{"bai":"Long Xuyên (thành phố)","t":"Long Xuyên trước đây là thành phố tỉnh lỵ cũ thuộc tỉnh An Giang, vùng Đồng bằng sông Cửu Long, Việt Nam."},"thach dong":{"bai":"Thạch Động thôn vân","t":"Thạch Động thôn vân , là tên hai bài thơ của Mạc Thiên Tứ; một bằng chữ Hán được xếp trong tập Hà Tiên thập vịnh (khắc in năm 1737), và một bằng chữ Nôm được xếp trong tập Hà Tiên thập cảnh khúc vịnh. Cả hai bài đều mô tả cảnh đẹp của núi Thạch Động, một trong mười thắng cảnh của đất Hà Tiên xưa; nay thuộc phường Hà Tiên, tỉnh An Giang, Việt Nam."},"cong tam quan":{"bai":"Cổng tam quan","t":"Cổng tam quan là một loại cổng có ba lối đi thường thấy ở chùa chiền theo lối kiến trúc truyền thống Việt Nam. Một số dinh thự, và đình miếu cũng xây loại cổng này như Cơ Mật viện ở Huế."},"dao hon khoai":{"bai":"Quần đảo Hòn Khoai","t":"Quần đảo Hòn Khoai (tên cũ: Giáng Hương, Ile Independence, Paulo Obi, Pulo Ubi, Pulo Oby) là tên một cụm đảo thuộc tỉnh Cà Mau, trong đó đảo chính là Hòn Khoai."},"vuon quoc gia u minh ha":{"bai":"Vườn quốc gia U Minh Hạ","t":"Vườn quốc gia U Minh Hạ thuộc tỉnh Cà Mau. Địa giới hành chính nằm trên xã Khánh Lâm, Khánh An và Đá Bạc. Được thành lập theo quyết định số 112/QĐ-TTg ngày 20 tháng 1 năm 2006 của Thủ tướng chính phủ Cộng hòa Xã hội Chủ nghĩa Việt Nam, trên cơ sở nâng cấp khu bảo tồn thiên nhiên Vồ Dơi."},"dam thi tuong":{"bai":"Đầm Thị Tường","t":"Đầm Thị Tường (hay đầm Bà Tường) là một đầm nước tự nhiên tại tỉnh Cà Mau, Việt Nam. Đây là đầm nước có diện tích lớn nhất vùng Đồng bằng sông Cửu Long, được mệnh danh là \"biển hồ giữa đồng bằng\". Đầm nằm cách phường Tân Thành 40 km về hướng tây nam, tại ranh giới hai xã Phú Mỹ và Trần Văn Thời thuộc tỉnh Cà Mau."},"canh dong dien gio bac lieu":{"bai":"Nhà máy điện gió Bạc Liêu","t":"Nhà máy điện gió Bạc Liêu là nhà máy điện gió đặt tại khóm Biển Đông A, phường Hiệp Thành, tỉnh Cà Mau (xã Vĩnh Trạch Đông, thành phố Bạc Liêu, tỉnh Bạc Liêu cũ). Đây là nhà máy điện gió ven biển đầu tiên của Việt Nam và lớn nhất cả nước, được xây từ năm 2010. Từ tháng 6 năm 2013 đến tháng 3 năm 2020 đã đóng góp cho mạng lưới điện quốc gia 1 tỷ kWh."},"nha cong tu bac lieu":{"bai":"Công tử Bạc Liêu","t":"Công tử Bạc Liêu là cụm từ dân gian ở miền Nam Việt Nam đặt ra vào cuối thế kỷ 19 đến đầu thế kỷ 20 để chỉ các công tử, con của những gia đình giàu có sống ở tỉnh Bạc Liêu (nay là tỉnh Cà Mau), trong thời kỳ xã hội Việt Nam thời Pháp thuộc. Vào lúc này, thực dân Pháp đã ổn định về tổ chức của vùng đất thuộc địa Nam Kỳ. Việc phân chia lại ruộng đất đã tạo nên rất nhiều đại điền chủ ở vùng đất này."},"chua xiem can":{"bai":"Chùa Xiêm Cán","t":"Chùa Xiêm Cán nằm tại đường Huyện 31, khóm Biển Đông B, phường Hiệp Thành, tỉnh Cà Mau, là công trình kiến trúc nổi bật và là nơi tổ chức các lễ hội hàng năm của người Khmer. Chùa có khuôn viên rộng 4 ha, là quần thể kiến trúc tôn giáo lớn bậc nhất khu vực Đồng bằng sông Cửu Long."},"ben ninh kieu":{"bai":"Bến Ninh Kiều","t":"Bến Ninh Kiều, nay được gọi là Công viên Ninh Kiều, là một bến nước và là địa danh du lịch, văn hóa của thành phố Cần Thơ hình thành từ thế kỷ XIX. Bến Ninh Kiều tọa lạc ở bờ phải sông Hậu, nằm giữa ngã ba sông Hậu và sông Cần Thơ tiếp giáp với đường Hai Bà Trưng, phường Ninh Kiều thuộc thành phố Cần Thơ."},"cho noi cai rang":{"bai":"Chợ nổi Cái Răng","t":"Chợ nổi Cái Răng là chợ nổi đầu mối chuyên mua bán trái cây và rau củ ở trên sông Cần Thơ và là điểm tham quan đặc sắc của phường Cái Răng, thành phố Cần Thơ. Năm 2016, Chợ nổi Cái Răng đã được Bộ văn hóa thể thao và du lịch công nhận Di sản Văn hóa phi vật thể quốc gia."},"cho dem ninh kieu":{"bai":"Bến Ninh Kiều","t":"Bến Ninh Kiều, nay được gọi là Công viên Ninh Kiều, là một bến nước và là địa danh du lịch, văn hóa của thành phố Cần Thơ hình thành từ thế kỷ XIX. Bến Ninh Kiều tọa lạc ở bờ phải sông Hậu, nằm giữa ngã ba sông Hậu và sông Cần Thơ tiếp giáp với đường Hai Bà Trưng, phường Ninh Kiều thuộc thành phố Cần Thơ."},"nha co binh thuy":{"bai":"Nhà cổ Bình Thủy","t":"Nhà cổ Bình Thủy tên chính thức là Phủ thờ họ Dương hay còn gọi là nhà thờ họ Dương, nhà cổ vườn lan. Ngôi nhà tọa lạc tại số 142-144 đường Bùi Hữu Nghĩa, phường Bình Thủy, thành phố Cần Thơ. Ngôi nhà được xem là công trình kiểu mẫu đại biểu cho phong cách kiến trúc Đông Dương ở Nam Kỳ giai đoạn đầu thế kỷ 20. Ngôi nhà là điểm du lịch được yêu thích ở Cần Thơ."},"thien vien truc lam phuong nam":{"bai":"Thiền viện Trúc Lâm Phương Nam","t":"Thiền viện Trúc Lâm Phương Nam tọa lạc tại khu vực Mỹ Khánh, phường An Bình, thành phố Cần Thơ, Việt Nam. Đây là một thiền viện thuộc hàng lớn nhất ở miền Tây Nam Bộ, tính đến thời điểm năm 2014. Thiền viện được khởi công xây dựng vào ngày 16 tháng 7 năm 2013 (19 tháng 6 năm Quý Tỵ), trên một diện tích 38.016 m²."},"dinh binh thuy":{"bai":"Đình Bình Thủy","t":"Đình Bình Thủy, tên chữ là Long Tuyền Cổ Miếu là một đình thần tại Thành phố Cần Thơ. Đây là một công trình có giá trị về kiến trúc nghệ thuật cổ truyền của người Việt giai đoạn khai hoang miền Tây Nam Bộ."},"cho coc ly":{"bai":"Chợ phiên Cốc Ly","t":"Cốc Ly là một chợ vùng cao ở xã Bảo Nhai thuộc tỉnh Lào Cai. Chợ Cốc Ly được họp vào mỗi thứ 3 hàng tuần. Tuy không phải là một chợ lớn nhưng Cốc Ly rất quan trọng đối với đồng bào dân tộc ở phía tây Bắc Hà. Đây là nơi họp mặt, trao đổi, mua bán của người Mông Hoa, người Dao khuyển (Dao Đen) và người Nùng."},"thac tien sa":{"bai":"Thác Cát Cát","t":"Thác Cát Cát hay thác Tiên Sa là thác trên suối Cát Cát ở vùng đất bản Cát Cát xã Tả Van, tỉnh Lào Cai, Việt Nam. Thác Cát Cát là một trong những thắng cảnh du lịch nổi tiếng tại thị xã Sa Pa. Thác cách trung tâm thị trấn Sa Pa cỡ 3 km về phía tây."},"mui sa vi":{"bai":"Mũi Sa Vĩ","t":"Mũi Sa Vĩ, còn gọi là mũi Gót là mũi đất ở cực đông bắc Việt Nam tọa độ 21°29'33\" bắc, 108°4'5\" đông thuộc phường Móng Cái 1, thành phố Quảng Ninh. Phía bắc là cửa sông Bắc Luân đổ ra biển rộng khoảng 5 km nhìn ra hòn Dậu Gót (1/3 thuộc Việt Nam) đối diện đất Trung Quốc. Ở mũi Sa Vĩ có dựng một Bức phù điêu hình 3 ngọn thông vươn thẳng lên trời, trên ghi câu thơ của nhà thơ Tố Hữu: \"..."},"hon ga choi":{"bai":"Vịnh Hạ Long","t":"Vịnh Hạ Long là một vịnh nhỏ thuộc phần bờ tây vịnh Bắc Bộ tại khu vực biển Đông Bắc Việt Nam, bao gồm vùng biển đảo của khu vực đô thị Hạ Long thuộc thành phố Quảng Ninh."},"chua thay":{"bai":"Chùa Thầy","t":"Chùa Thầy là một nhóm những ngôi chùa ở chân núi Sài Sơn, xã Quốc Oai, thành phố Hà Nội (trước đây là huyện Quốc Oai, tỉnh Hà Tây), cách trung tâm thành phố khoảng 20 km về phía Tây nam, đi theo đường cao tốc Láng - Hòa Lạc. Sài Sơn có tên Nôm là núi Thầy, nên chùa được gọi là chùa Thầy. Chùa được xây dựng từ thời nhà Lý."},"chua tay phuong":{"bai":"Chùa Tây Phương","t":"Chùa Tây Phương là một ngôi chùa được xây trên đỉnh đồi Câu Lâu thuộc xã Tây Phương, thành phố Hà Nội."},"nha tho lon ha noi":{"bai":"Nhà thờ Lớn Hà Nội","t":"Nhà thờ Lớn Hà Nội (tên chính thức: Nhà thờ chính tòa Thánh Giuse, cũng gọi là Nhà thờ chính tòa Hà Nội) là nhà thờ chính tòa của Tổng giáo phận Hà Nội, nơi có ngai tòa của Tổng giám mục. Đây là một nhà thờ cổ kính tại thành phố này, thường xuyên diễn ra các sinh hoạt tín ngưỡng của các giáo dân Công giáo thuộc giáo xứ chính tòa cũng như của toàn tổng giáo phận."},"hang kho muong":{"bai":"Hang Kho Mường","t":"Hang Kho Mường hay Hang Dơi Kho Mường là hang ở vùng đất bản Kho Mường xã Pù Luông, tỉnh Thanh Hóa, Việt Nam. Hang thuộc dạng karst trong dãy núi đá vôi phu Kho Mường ở phía bắc bản Kho Mường, cách bản cỡ 2 km. Hang trong vùng lõi của Khu bảo tồn thiên nhiên Pù Luông. Các dãy núi đá vôi trong vùng Kho Mường còn giữ nguyên vẻ hoang sơ."},"bai dua":{"bai":"Bãi Dứa","t":"Bãi Dứa hay Bãi Hương Phong, hay Bãi Lãng Du, hay Bãi Hàng Bàng, là một bãi biển tại phường Vũng Tàu, Thành phố Hồ Chí Minh, Việt Nam. Tên gọi Bãi Dứa được người dân địa phương đặt bởi ngày trước tại bãi biển này có nhiều dứa dại mọc."},"cau thi nai":{"bai":"Cầu Thị Nại","t":"Cầu Thị Nại hay Cầu Nhơn Hội nằm tại phường Quy Nhơn Đông, tỉnh Gia Lai trong hệ thống cầu đường Nhơn Hội dài gần 7 km nối thành phố Quy Nhơn cũ với bán đảo Phương Mai (khu kinh tế Nhơn Hội), gồm cầu chính vượt đầm Thị Nại, 5 cầu nhỏ qua sông Hà Thanh và đường dẫn 2 đầu cầu. Công trình xây dựng cầu Thị Nại được khởi công vào ngày 3 tháng 11 năm 2002 và hoàn thành vào ngày 12 tháng 12 năm 2006."},"duc me mang den":{"bai":"Đức Mẹ Măng Đen","t":"Tượng Đức Mẹ Fatima tại Măng Đen (còn được là Tượng Đức Mẹ Măng Đen hay Tượng Đức Mẹ cụt tay) là một di tích, điểm hành hương Công giáo của Giáo phận Kon Tum, tọa lạc tại xã Măng Đen, tỉnh Quảng Ngãi, cạnh Quốc lộ 24, cách phường Kon Tum 53 km về phía Đông Bắc."},"dam lap an":{"bai":"Đầm Lập An","t":"Đầm Lập An (hay còn được gọi là Đầm An Cư, Vụng An Cư hoặc Đầm Lăng Cô) là một đầm nước lợ nằm cạnh đèo Phú Gia, bên bờ vịnh Lăng Cô, thuộc địa phận xã Chân Mây – Lăng Cô, thành phố Huế. Đây là một trong 12 đầm phá tiêu biểu của Miền Trung Việt Nam. Nằm ở khối núi Hải Vân – Bạch Mã, Đầm Lập An nằm trong ranh giới giữa hai miền khí hậu Bắc và Nam, trong vùng có tâm mưa lớn."},"hon mun":{"bai":"Hòn Mun","t":"Hòn Mun là một trong những hòn đảo thơ mộng nhất trong hệ thống đảo của Nha Trang. Hòn Mun cách cảng Cầu Đá 10 km (khoảng 45 phút đi tàu) và nằm ở phía Đông Nam đảo Bồng Nguyên. Không chỉ hấp dẫn bởi cát trắng, biển xanh, những tổ yến hoang sơ trên cheo leo vách đá... nơi đây còn nổi tiếng là một trong những \"thủy cung\" \"giàu và đẹp\" nhất của biển Đông Nam Á."},"nui ta cu":{"bai":"Núi Tà Cú","t":"Núi Tà Cú cao 649 m, nằm ven Quốc lộ 1, thuộc xã Hàm Thuận Nam, cách Phan Thiết 28 km về phía Nam là một thắng cảnh và là một điểm leo núi của tỉnh Lâm Đồng. Tên gọi tà kóu bắt nguồn từ tiếng Chăm cổ \"tà\" là núi và \"kóu\" là già. Nghĩa là \"núi già\". Núi Tà Cú hiện nay được xem là địa điểm linh thiêng phục vụ cho du lịch tâm linh, hành hương đến các ngôi chùa núi Tà Cú (Linh Sơn Trường thọ)."},"bau trang":{"bai":"Bàu Trắng","t":"Bàu Trắng (hay Bàu Cát, Bạch Hồ, Bàu Sen) là một hồ nước ngọt ở thôn Hồng Lâm, xã Hòa Thắng, tỉnh Lâm Đồng, cách Phan Thiết khoảng 62 km về hướng Đông Bắc."},"nha day buon ma thuot":{"bai":"Nhà đày Buôn Ma Thuột","t":"Nhà Đày Buôn Ma Thuột là một di tích lịch sử tại Đắk Lắk, Việt Nam với kết cấu là một di tích hệ thống nhà tù (nhà đày) cũ từ thời Pháp thuộc, hiện đang do Sở Văn hóa - Thể thao và Du lịch tỉnh Đắk Lắk quản lý. Trước đó, từ 1975 đến 1979 Nhà đày được giao cho Công an Đắk Lắk quản lý. Từ năm 1979, Nhà đày thuộc sự quản lý của Công ty Văn hoá - Thông tin Đắk Lắk."},"mui dien":{"bai":"Mũi Điện","t":"Mũi Điện (còn được gọi là Mũi Đại Lãnh) là một mũi đất nhô ra biển từ một nhánh của dãy Trường Sơn, hướng thẳng ra bãi Môn, thuộc địa phận xã Hòa Xuân, tỉnh Đắk Lắk, Việt Nam."},"nha tho mang lang":{"bai":"Nhà thờ Mằng Lăng","t":"Nhà thờ Mằng Lăng là một nhà thờ Công giáo nằm trên địa phận xã Tuy An Đông, tỉnh Đắk Lắk. Đây là nhà thờ thuộc Giáo xứ Mằng Lăng, là nơi sinh của Chân phước Anrê Phú Yên, một trong những vị tử đạo bổn mạng của giáo lý viên và những người trẻ Công giáo. Nhà thờ hiện nay cũng là nơi hành hương vào dịp lễ kỷ niệm Chân phước Anrê Phú Yên và thánh lễ cầu cho giới trẻ Công giáo Việt Nam."},"dam o loan":{"bai":"Đầm Ô Loan","t":"Đầm Ô Loan là một đầm ở Đắk Lắk, đây là một thắng cảnh cấp quốc gia của Việt Nam, một danh lam tiêu biểu của tỉnh."},"vinpearl safari phu quoc":{"bai":"Công viên Chăm sóc và Bảo tồn Động vật Vinpearl Safari Phú Quốc","t":"Công viên Chăm sóc và Bảo tồn Động vật Vinpearl Safari Phú Quốc là một vườn thú ở đặc khu Phú Quốc, tỉnh An Giang, Việt Nam. Công viên được tập đoàn Vingroup đầu tư và khai trương ngày 24 tháng 12 năm 2015. Đây được xem là vườn thú Safari lớn nhất Việt Nam."},"suoi tranh":{"bai":"Suối Tranh","t":"Suối Tranh là một địa điểm tham quan nổi tiếng đối với khách du lịch trong và ngoài nước khi đến tham quan tại đặc khu Phú Quốc. Trước kia Suối Tranh còn rất hoang sơ và là một trong những điểm nghỉ ngơi giải trí của dân địa phương sau những ngày làm việc mệt mỏi và mỗi khi có lễ hội lớn trên đảo. Suối Tranh chảy qua nhiều địa hình, vị trí hiểm trở tạo nên những con thác, những hồ nước sâu."},"dinh cau":{"bai":"Dinh Cậu","t":"Dinh Cậu là một di tích tọa lạc tại khu phố 2, đặc khu Phú Quốc, tỉnh An Giang, Việt Nam. Đây là một điểm đến, thu hút nhiều du khách."},"vuon quoc gia con dao":{"bai":"Vườn quốc gia Côn Đảo","t":"Vườn quốc gia Côn Đảo là một vườn quốc gia nằm trên địa bàn đặc khu Côn Đảo, Thành phố Hồ Chí Minh, Việt Nam. Vườn quốc gia được thành lập theo Quyết định số 135/QĐ-TTg ngày 31 tháng 3 năm 1993 của Thủ tướng chính phủ Cộng hòa Xã hội Chủ nghĩa Việt Nam."},"hon bay canh":{"bai":"Côn Đảo","t":"Côn Đảo là một đặc khu thuộc Thành phố Hồ Chí Minh, Việt Nam. Tên đặc khu được kế thừa cho huyện đảo Côn Đảo, tỉnh Bà Rịa – Vũng Tàu trước đây. Đây vốn là một quần đảo nằm ở ngoài khơi bờ biển Nam Bộ, cách phường Vũng Tàu 97 hải lý theo đường biển. Nơi gần Côn Đảo nhất trên đất liền là xã Vĩnh Hải, thành phố Cần Thơ là 40 hải lý."},"quan dao nam du":{"bai":"Quần đảo Nam Du","t":"Quần đảo Nam Du là một quần đảo nằm về phía đông nam đảo Phú Quốc trong vịnh Thái Lan, cách bờ biển Rạch Giá 115 km. Quần đảo nằm dưới sự quản lý của đặc khu Kiên Hải thuộc tỉnh An Giang."},"hon mau":{"bai":"Hòn Mấu","t":"Hòn Mấu là một hòn đảo trong quần đảo Nam Du, thuộc đặc khu Kiên Hải, tỉnh An Giang, Việt Nam. Xưa kia, trên hòn đảo có rất nhiều dây mấu, một loại dây rừng dùng để làm thuốc Nam hoặc để cột dây tiêu, vì thế mà còn tên gọi Hòn Mấu."},"hon ngang":{"bai":"Hòn Ngang","t":"Hòn Ngang là một hòn đảo trong quần đảo Nam Du, thuộc đặc khu Kiên Hải, tỉnh An Giang, Việt Nam. Trong 21 hòn đảo ở quần đảo Nam Du, thì 20 hòn đảo đều có hình dạng phân bố theo chiều dọc, chỉ duy nhất hòn đảo lại nằm theo chiều ngang, do đó mà có tên gọi là Hòn Ngang."},"khu du lich sinh thai vam sat":{"bai":"Khu du lịch sinh thái Vàm Sát","t":"Khu du lịch sinh thái Vàm Sát là một khu du lịch sinh thái rừng ngập mặn Vàm Sát bên trong Khu dự trữ sinh quyển Cần Giờ, huyện Cần Giờ, Thành phố Hồ Chí Minh. Khu du lịch này chủ yếu khai thác yếu tố hoang sơ của vùng sinh thái ngập mặn có hệ động thực vật đặc thù, đa dạng. Đây là nơi cư dân thành phố nghỉ ngơi cuối tuần tránh xa thành phố ô nhiễm, ồn ào để tìm về với thiên nhiên."},"ho coc":{"bai":"Hồ Cốc","t":"Hồ Cốc là một bãi biển nằm trên địa bàn xã Xuyên Mộc, thuộc Thành phố Hồ Chí Minh. Nơi đây được biết đến với vẻ đẹp hoang sơ, bãi cát trắng mịn trải dài, làn nước trong xanh và không gian yên bình, tách biệt khỏi sự ồn ào của đô thị."},"cho noi ca mau":{"bai":"Chợ nổi Cà Mau","t":"Chợ nổi Cà Mau là một chợ nổi trên sông Gành Hào, cách cầu Gành Hào khoảng hơn 200 m, thuộc địa bàn phường Lý Văn Lâm, tỉnh Cà Mau. Ngày trước, chợ ở giữa ngã ba chùa Bà cách đó khoảng hơn chục cây số. Xưa kia, đây là nơi tụ tập kiếm sống của người tứ xứ và bán nhiều loại hàng hóa khác nhau. Bây giờ, chợ chỉ còn bán các sản vật của miệt vườn."},"con dao":{"bai":"Côn Đảo","t":"Côn Đảo là một đặc khu thuộc Thành phố Hồ Chí Minh, Việt Nam. Tên đặc khu được kế thừa cho huyện đảo Côn Đảo, tỉnh Bà Rịa – Vũng Tàu trước đây. Đây vốn là một quần đảo nằm ở ngoài khơi bờ biển Nam Bộ, cách phường Vũng Tàu 97 hải lý theo đường biển. Nơi gần Côn Đảo nhất trên đất liền là xã Vĩnh Hải, thành phố Cần Thơ là 40 hải lý."}};
